function build_satellite_top()
% BUILD_SATELLITE_TOP  一键程序化生成 sim/model/satellite_top.slx
%                      —— v3：整星闭环集成（任务 0711-01，接口册附录 AE）
% ！本脚本必须在装有 MATLAB/Simulink R2023b+ 的机器上运行，它才会生成 .slx；
% ！本仓库/本对话中不存在预生成的 v3 .slx（仓内旧 .slx 为 0707-02 骨架产物，
%   本脚本运行时会删除重建）。
%
% v3 相对 v2 骨架（0707-02）的集成改造（原文骨架见 git 历史 / 附录 C）：
%  [改1] 14 路占位源退役 11 路：遥测/真值全部改由真子系统供给（K.5 归位：
%        src_soh 的 '100' 百分数占位 → power_ecm/5 的 0–1 口径 SOH；
%        M.4：src_rw_btemp / src_bat_temp 退役 → thermal_net Out1/Out2）。
%        仅 labels 三路 Const 占位保留（权威 labels 由 run_dev_s001.m
%        后处理生成，附录 AE.4——模型内 labels 记录不入 §simout）。
%  [改2] 三个已冻结子系统按 [查13]（build_bat_dualscale）跨模型复制：
%        rw_assembly_dev/{rw_speed_ctrl, rw_assembly}（Y.2 复合体边界，
%        0710-02 的局部热节点退役，轴承温度改由热网络供给）、
%        power_ecm_dev/power_ecm（K.2 外形冻结）、
%        thermal_net_dev/thermal_net（M.2 端口冻结）。
%  [改3] 驱动侧 From Workspace ×5：env_sun/env_r（Interpolate on）、
%        env_flag（off + ZeroCross off，前值保持）、env_beta（on）、
%        prof_cmd_rpm（on，折线剖面线性插值恰为精确重建）——
%        与 0709-01 thermal harness [查7] 同构；编译桩由
%        thermal_params/sat_params 预置，run_dev_s001.m 覆写真数据。
%  [改4] 热接线照抄 M.2 表：In4 = i²·R（prod_i2 → Gain rw.r_ohm）、
%        In5 = Mf·ω（Out3 × Out1·π/30）、In6 = power_ecm Out4 q_gen_w；
%        Out1 → rw_assembly In2（LUT 温度轴）+ 遥测，Out2 → power_ecm In2
%        （25 ℃ 恒温桩拆除）+ 遥测；Out3–5 诊断口接 Terminator 不入 §5。
%  [改5] 负载律（AE.2）：eclipse_flag → 1-D LUT（断点 sat.load_flag_bp、
%        表值 sat.load_i_by_flag、Linear+Clip）→ power_ecm In1。
%  [改6] SOH 停机机构（尾巴用，与判据分离，AE.4/[查2]）：
%        power_ecm/5 → Compare To Constant(<= sat.soh_stop_run,
%        ZeroCross off) → Stop（承 bat_dualscale [查16]）。
%  [改7] 求解器改定步长 ode4 @ sat.fixed_step_s=2e-3（承 0708-03/0710-02
%        [查9][查13]：电流环极点 −2π·100 rad/s 的 RK4 稳定裕度 2.2×）；
%        v2 的 Rate Transition 双档退役，改 To Workspace Decimation
%        5000/500 ⇔ 10 s/1 s（承 0710-02 记录法；虚拟总线过 RT 的版本
%        兼容坑就此绕开）。
%  [改8] 总线扩展：TelemetryBus 6→10（+eclipse_flag,+beta_deg,
%        +rw_cmd_torque_nm,+bat_soc）、TruthBus 5→6（+rw_lube_level）、
%        LabelsBus 3 不变；元素序即 Bus Creator 端口序（satellite_buses.m
%        由本脚本重新生成）。模型内一律 double，§5.1 文件 dtype 由
%        save_simout.m 落盘时统一转换（附录 AF.2）。
%  [改9] rw_assembly Out6/Out7（fail_flag/mode）接 Terminator：§5 无此
%        遥测通道，权威失效判定在 labels 后处理层（AE.4）。
%
% 用法（仓库根目录 rul-space/ 下）：
%   >> addpath('sim/model'); build_satellite_top
% 随后：
%   >> sat_selftest            % S0–S9 快档验收（<10 min）
%   >> run_dev_s001 rwa        % 两条 dev 全寿命曲线（详见教程）
%   >> run_dev_s001 bat
%
% 版本：v3.0（0711-01）

mdl     = 'satellite_top';
here    = fileparts(mfilename('fullpath'));      % 期望位于 sim/model/
slxPath = fullfile(here, [mdl '.slx']);
fprintf('[build_satellite_top] 版本 v3.0（0711-01 整星闭环集成）\n');
if bdIsLoaded(mdl), close_system(mdl, 0); end
if exist(slxPath, 'file'), delete(slxPath); end
addpath(here);

% ---------- 0. 三个子系统源模型：缺则先构建（一键纪律） ----------
srcs = {'power_ecm_dev',   @build_power_ecm;
        'rw_assembly_dev', @build_rw_assembly;
        'thermal_net_dev', @build_thermal_net};
for k = 1:size(srcs,1)
    p = fullfile(here, [srcs{k,1} '.slx']);
    if ~exist(p, 'file')
        fprintf('  [依赖] %s 缺失 → 先运行 %s\n', srcs{k,1}, func2str(srcs{k,2}));
        feval(srcs{k,2});
        if bdIsLoaded(srcs{k,1}), close_system(srcs{k,1}, 0); end
    end
end

% ---------- 1. 参数 + Bus 定义（元素序 = 端口序，[改8]） ----------
sat_params();                                    % 含 rw/bat/thm + 编译桩
busScript = fullfile(here, 'satellite_buses.m');
write_bus_script(busScript);
satellite_buses();

% ---------- 2. 新建模型与求解器配置（[改7]） ----------
new_system(mdl);
set_param(mdl, ...
    'SolverType','Fixed-step', 'Solver','ode4', ...
    'FixedStep','sat.fixed_step_s', ...
    'StopTime','sat.stop_time_s', ...
    'SaveFormat','Dataset', ...
    'SaveTime','off', 'SaveOutput','off', 'SaveState','off', ...
    'SignalLogging','off', 'DSMLogging','off', ...
    'SimCompilerOptimization','on', ...
    'ReturnWorkspaceOutputs','on', 'ReturnWorkspaceOutputsName','out', ...
    'PreLoadFcn', ['if ~evalin(''base'',''exist(''''sat'''',''''var'''')''), ' ...
    'try, sat_params; catch, ' ...
    'warning(''sat_params.m not on path: addpath sim/model first''); end, end']);

% ---------- 3. 驱动侧 From Workspace ×5（[改3]） ----------
add_block('simulink/Sources/From Workspace',[mdl '/fw_sun'], ...
    'VariableName','env_sun','SampleTime','0','Interpolate','on', ...
    'OutputAfterFinalValue','Holding final value','Position',[30 40 130 70]);
add_block('simulink/Sources/From Workspace',[mdl '/fw_r'], ...
    'VariableName','env_r','SampleTime','0','Interpolate','on', ...
    'OutputAfterFinalValue','Holding final value','Position',[30 100 130 130]);
add_block('simulink/Sources/From Workspace',[mdl '/fw_flag'], ...
    'VariableName','env_flag','SampleTime','0','Interpolate','off', ...
    'OutputAfterFinalValue','Holding final value','ZeroCross','off', ...
    'Position',[30 160 130 190]);
add_block('simulink/Sources/From Workspace',[mdl '/fw_beta'], ...
    'VariableName','env_beta','SampleTime','0','Interpolate','on', ...
    'OutputAfterFinalValue','Holding final value','Position',[30 220 130 250]);
add_block('simulink/Sources/From Workspace',[mdl '/fw_cmd_rpm'], ...
    'VariableName','prof_cmd_rpm','SampleTime','0','Interpolate','on', ...
    'OutputAfterFinalValue','Holding final value','Position',[30 300 130 330]);

% ---------- 4. 三个子系统跨模型复制（[改2]） ----------
load_system('rw_assembly_dev');
load_system('power_ecm_dev');
load_system('thermal_net_dev');
add_block('rw_assembly_dev/rw_speed_ctrl',[mdl '/rw_speed_ctrl'], ...
    'Position',[300 290 420 370]);
add_block('rw_assembly_dev/rw_assembly',  [mdl '/rw_assembly'], ...
    'Position',[520 280 680 440]);
add_block('power_ecm_dev/power_ecm',      [mdl '/power_ecm'], ...
    'Position',[520 520 680 660]);
add_block('thermal_net_dev/thermal_net',  [mdl '/thermal_net'], ...
    'Position',[300 40 460 230]);
close_system('rw_assembly_dev', 0);
close_system('power_ecm_dev',   0);
close_system('thermal_net_dev', 0);

% ---------- 5. 胶合块 ----------
% —— 剖面/反馈换算（Y.2：ctrl In1/In2 为 rad/s）——
add_block('simulink/Math Operations/Gain',[mdl '/g_cmd_rpm2rad'], ...
    'Gain','pi/30','Position',[180 300 220 330]);
add_block('simulink/Math Operations/Gain',[mdl '/g_fb_rpm2rad'], ...
    'Gain','pi/30','Orientation','left','Position',[400 430 440 460]);
% —— 热接线换算（[改4]）——
add_block('simulink/Math Operations/Product',[mdl '/prod_i2'], ...
    'Inputs','2','Position',[740 300 770 340]);            % i×i
add_block('simulink/Math Operations/Gain',[mdl '/g_pcu'], ...
    'Gain','rw.r_ohm','Position',[800 305 840 335]);       % i²R → thermal In4
add_block('simulink/Math Operations/Gain',[mdl '/g_w_rpm2rad'], ...
    'Gain','pi/30','Position',[740 360 780 390]);          % ω rpm→rad/s
add_block('simulink/Math Operations/Product',[mdl '/prod_pfric'], ...
    'Inputs','2','Position',[820 365 850 405]);            % Mf×ω → thermal In5
% —— 负载律（[改5]）——
add_block('simulink/Lookup Tables/1-D Lookup Table',[mdl '/lut_iload'], ...
    'NumberOfTableDimensions','1', ...
    'BreakpointsForDimension1','sat.load_flag_bp', ...
    'Table','sat.load_i_by_flag', ...
    'InterpMethod','Linear','ExtrapMethod','Clip', ...
    'Position',[180 155 240 195]);
% —— SOH 停机（[改6]）——
add_block('simulink/Logic and Bit Operations/Compare To Constant', ...
    [mdl '/cmp_soh'],'relop','<=','const','sat.soh_stop_run', ...
    'ZeroCross','off','Position',[740 560 810 590]);
add_block('simulink/Sinks/Stop Simulation',[mdl '/stop_at_soh'], ...
    'Position',[850 560 890 590]);
% —— truth 派生（bat.lli = 1−soh 一阶等价，AE.2；lam v1 恒 0 占位）——
add_block('simulink/Sources/Constant',[mdl '/const_one'], ...
    'Value','1','Position',[740 630 770 660]);
add_block('simulink/Math Operations/Sum',[mdl '/sum_lli'], ...
    'Inputs','+-','Position',[800 640 820 660]);
add_block('simulink/Sources/Constant',[mdl '/src_lam'], ...
    'Value','0','Position',[740 690 770 720]);
% —— labels 占位（[改1]）——
add_block('simulink/Sources/Constant',[mdl '/src_rul'], ...
    'Value','1e4','Position',[900 760 960 790]);
add_block('simulink/Sources/Constant',[mdl '/src_hi'], ...
    'Value','0','Position',[900 820 960 850]);
add_block('simulink/Sources/Constant',[mdl '/src_fail'], ...
    'Value','0','Position',[900 880 960 910]);
% —— 诊断口收尾（[改9]）——
for t = {'term_rw_fail','term_rw_mode','term_th3','term_th4','term_th5'}
    add_block('simulink/Sinks/Terminator',[mdl '/' t{1}], ...
        'Position', pos_next(t{1}));
end

% ---------- 6. 三个 Bus Creator（[改8]） ----------
add_block('simulink/Signal Routing/Bus Creator',[mdl '/bus_telemetry'], ...
    'Inputs','10','OutDataTypeStr','Bus: TelemetryBus', ...
    'Position',[1050  30 1060 560]);
add_block('simulink/Signal Routing/Bus Creator',[mdl '/bus_truth'], ...
    'Inputs','6','OutDataTypeStr','Bus: TruthBus', ...
    'Position',[1050 600 1060 740]);
add_block('simulink/Signal Routing/Bus Creator',[mdl '/bus_labels'], ...
    'Inputs','3','OutDataTypeStr','Bus: LabelsBus', ...
    'Position',[1050 760 1060 910]);

% ---------- 7. 接线 ----------
% —— 驱动 → 子系统 ——
add_line(mdl,'fw_sun/1',     'thermal_net/1','autorouting','on');
add_line(mdl,'fw_r/1',       'thermal_net/2','autorouting','on');
add_line(mdl,'fw_flag/1',    'thermal_net/3','autorouting','on');
add_line(mdl,'fw_flag/1',    'lut_iload/1',  'autorouting','on');
add_line(mdl,'fw_cmd_rpm/1', 'g_cmd_rpm2rad/1','autorouting','on');
add_line(mdl,'g_cmd_rpm2rad/1','rw_speed_ctrl/1','autorouting','on');
% —— 速度环闭合（Y.2）——
add_line(mdl,'rw_speed_ctrl/1','rw_assembly/1','autorouting','on');
add_line(mdl,'rw_assembly/1','g_fb_rpm2rad/1','autorouting','on');
add_line(mdl,'g_fb_rpm2rad/1','rw_speed_ctrl/2','autorouting','on');
% —— 热接线（[改4]）——
add_line(mdl,'rw_assembly/2','prod_i2/1','autorouting','on');
add_line(mdl,'rw_assembly/2','prod_i2/2','autorouting','on');
add_line(mdl,'prod_i2/1','g_pcu/1','autorouting','on');
add_line(mdl,'g_pcu/1','thermal_net/4','autorouting','on');
add_line(mdl,'rw_assembly/1','g_w_rpm2rad/1','autorouting','on');
add_line(mdl,'rw_assembly/3','prod_pfric/1','autorouting','on');
add_line(mdl,'g_w_rpm2rad/1','prod_pfric/2','autorouting','on');
add_line(mdl,'prod_pfric/1','thermal_net/5','autorouting','on');
add_line(mdl,'power_ecm/4','thermal_net/6','autorouting','on');
add_line(mdl,'thermal_net/1','rw_assembly/2','autorouting','on');
add_line(mdl,'thermal_net/2','power_ecm/2','autorouting','on');
% —— 负载 → 电池（[改5]）——
add_line(mdl,'lut_iload/1','power_ecm/1','autorouting','on');
% —— 停机（[改6]）——
add_line(mdl,'power_ecm/5','cmp_soh/1','autorouting','on');
add_line(mdl,'cmp_soh/1','stop_at_soh/1','autorouting','on');
% —— lli/lam ——
add_line(mdl,'const_one/1','sum_lli/1','autorouting','on');
add_line(mdl,'power_ecm/5','sum_lli/2','autorouting','on');
% —— 诊断口收尾（[改9]）——
add_line(mdl,'rw_assembly/6','term_rw_fail/1','autorouting','on');
add_line(mdl,'rw_assembly/7','term_rw_mode/1','autorouting','on');
add_line(mdl,'thermal_net/3','term_th3/1','autorouting','on');
add_line(mdl,'thermal_net/4','term_th4/1','autorouting','on');
add_line(mdl,'thermal_net/5','term_th5/1','autorouting','on');

% —— 总线馈线（带名连线，[修1] 承 v2）——
wire_named(mdl, ...
    {'fw_flag/1','fw_beta/1','rw_assembly/1','rw_assembly/2', ...
     'rw_speed_ctrl/1','thermal_net/1','power_ecm/1','power_ecm/2', ...
     'thermal_net/2','power_ecm/3'}, ...
    'bus_telemetry', ...
    {'eclipse_flag','beta_deg','rw_speed_rpm','rw_motor_current_a', ...
     'rw_cmd_torque_nm','rw_bearing_temp_c','bat_voltage_v','bat_current_a', ...
     'bat_temp_c','bat_soc'});
wire_named(mdl, ...
    {'rw_assembly/3','rw_assembly/4','rw_assembly/5', ...
     'power_ecm/5','sum_lli/1','src_lam/1'}, ...
    'bus_truth', ...
    {'rw_friction_torque_nm','rw_wear_volume_mm3','rw_lube_level', ...
     'bat_soh','bat_lli','bat_lam'});
wire_named(mdl, {'src_rul/1','src_hi/1','src_fail/1'}, 'bus_labels', ...
    {'rul','hi','fail'});

% ---------- 8. 双档记录（[改7]：Decimation 5000/500 ⇔ 10 s/1 s） ----------
buses = {'telemetry','truth','labels'};
yBase = [200 640 830];
for i = 1:numel(buses)
    b = buses{i}; y = yBase(i);
    add_block('simulink/Sinks/To Workspace',[mdl '/log_' b '_01hz'], ...
        'VariableName',sprintf('%s_01hz',b),'SaveFormat','Timeseries', ...
        'Decimation','5000','Position',[1150 y-20 1260 y+20]);
    add_block('simulink/Sinks/To Workspace',[mdl '/log_' b '_1hz'], ...
        'VariableName',sprintf('%s_1hz',b),'SaveFormat','Timeseries', ...
        'Decimation','500','Position',[1150 y+50 1260 y+90]);
    add_line(mdl, sprintf('bus_%s/1',b), sprintf('log_%s_01hz/1',b), ...
        'autorouting','on');
    add_line(mdl, sprintf('bus_%s/1',b), sprintf('log_%s_1hz/1',b), ...
        'autorouting','on');
end

% ---------- 9. 同步编译校验 + 存盘（承 v2 [修3]） ----------
feval(mdl, [], [], [], 'compile');   % 接口/命名/采样问题在此同步报错
feval(mdl, [], [], [], 'term');
save_system(mdl, slxPath);
fprintf('[OK] 已生成 %s（compile/term 校验通过）\n', slxPath);
fprintf('     下一步验收：>> sat_selftest\n');
end

% ======================================================================
function wire_named(mdl, srcs, busBlk, names)
% 连线并把信号线命名为总线元素名——Bus 对象指定后这是强制要求（承 v2 [修1]）。
% srcs 为完整 'blk/port' 串；同一源多分支时仅在馈入总线的分支命名一次，
% 信号名沿源传播，不与未命名分支冲突。
for k = 1:numel(srcs)
    h = add_line(mdl, srcs{k}, sprintf('%s/%d',busBlk,k), 'autorouting','on');
    set_param(h, 'Name', names{k});
end
end

function p = pos_next(name)
% Terminator 摆位小助手（只影响画面，不影响功能）
switch name
    case 'term_rw_fail', p = [720 460 740 480];
    case 'term_rw_mode', p = [760 460 780 480];
    case 'term_th3',     p = [500 40 520 60];
    case 'term_th4',     p = [500 80 520 100];
    otherwise,           p = [500 120 520 140];
end
end

function write_bus_script(fp)
lines = {
'% satellite_buses.m —— telemetry/truth/labels 三条 Bus 定义（v3，附录 AE.1 口径）'
'% 由 build_satellite_top.m 自动生成；模型 PreLoadFcn 经 sat_params 间接依赖本函数。'
'% 元素序 = Bus Creator 端口序 = 附录 AE.1 冻结表行序；模型内一律 double，'
'% §5.1 文件 dtype 由 save_simout.m 落盘时统一转换（附录 AF.2）。'
'function satellite_buses()'
'mk = @(names) make_bus(names);'
['assignin(''base'',''TelemetryBus'', mk({''eclipse_flag'',''beta_deg'',' ...
 '''rw_speed_rpm'',''rw_motor_current_a'',''rw_cmd_torque_nm'',' ...
 '''rw_bearing_temp_c'',''bat_voltage_v'',''bat_current_a'',' ...
 '''bat_temp_c'',''bat_soc''}));']
['assignin(''base'',''TruthBus'',     mk({''rw_friction_torque_nm'',' ...
 '''rw_wear_volume_mm3'',''rw_lube_level'',''bat_soh'',''bat_lli'',''bat_lam''}));']
'assignin(''base'',''LabelsBus'',    mk({''rul'',''hi'',''fail''}));'
'end'
'function b = make_bus(names)'
'elems = Simulink.BusElement.empty;'
'for i = 1:numel(names)'
'    e = Simulink.BusElement; e.Name = names{i}; e.DataType = ''double'';'
'    elems(i) = e;'
'end'
'b = Simulink.Bus; b.Elements = elems;'
'end'
};
fid = fopen(fp,'w'); fprintf(fid,'%s\n',lines{:}); fclose(fid);
end

