function build_thermal_net()
% BUILD_THERMAL_NET  一键程序化生成 sim/model/thermal_net_dev.slx（任务 0709-01）
% ！本脚本必须在装有 MATLAB/Simulink R2023b+ 的机器上运行，它才会生成 .slx；
% ！本仓库/本对话中不存在预生成的 .slx（与 build_rw_assembly / build_power_ecm /
%   build_satellite_top 同一纪律）。
%
% 生成物 thermal_net_dev.slx 含两部分：
%   ① thermal_net —— 本任务交付的子系统（env 环境 + 内热进 → 节点温度出）：
%        热源 q_solar = illum(eclipse_flag)·( q_track + q_zen·max(0, ŝ·r̂) )
%          —— 跟踪帆板项承载『地影开关』，天顶体装面项承载『太阳矢量』
%          （对地定向假设：天顶方向 = r̂ = r_eci/|r|）；
%        4 节点集总参数网络（结构板/轮体/轴承/电池）：
%          C_str·Ṫ = q_solar + q_earth + G_ws(T_whl−T_str) + G_bs(T_bat−T_str)
%                     − εσA_rad(T_str⁴ − T_space⁴)
%          C_whl·Ṫ = q_rw_motor + G_ws(T_str−T_whl) + G_bw(T_brg−T_whl)
%          C_brg·Ṫ = q_rw_fric  + G_bw(T_whl−T_brg)
%          C_bat·Ṫ = q_bat      + G_bs(T_str−T_bat)
%        内部一律 K，出口换算 °C：rw_bearing_temp_c / bat_temp_c（§6.5 通道）
%        + whl/str 温度与 q_solar_w 诊断口（模型内信号，不入 §6.5/§5，同 K.2
%        之 q_gen_w 先例）。
%   ② 验收 harness —— From Workspace 三路 env 驱动（sun/r 线性插值、flag 前值
%        保持）+ 三路内热常值（代表值，0711-01 换实时信号）+ 五路 To Workspace。
%        thermal_params 已装常值桩 env_*，模型任何时候可编译；thermal_selftest
%        在 load_system 后以 import_gmat('LEO550_B00'/'B82', fixtures) 覆写。
%
% v1 自查记录（沙箱 Python oracle 交叉验证后定稿，详见设计报告 §5）：
%  [查1] 热源双承载设计：若只用天顶余弦项，β≈0 时地影恰与 cos≤0 重合，
%        『地影开关』永不可证伪；若只用跟踪帆板项，『太阳矢量』沦为摆设。
%        两项并置后 selftest T7（逐样本热源核对）与 T8（β 几何）可分别证伪。
%  [查2] 平衡不动点闭式解：常值桩下把初值置于解析平衡（结构板辐射=全部输入、
%        节点差=q/G），oracle O2 实测 2000 s 漂移 0.00e+00 K —— 网络接线与
%        K→°C 换算链由此逐位锁定（selftest T2 同式复验）。
%  [查3] 能量审计：oracle 以辅助积分状态同积分器核对 ΣCᵢΔTᵢ = ∫(输入−辐射)dt，
%        B00 三轨相对残差 6.9e-12 —— 任何传导符号不对称在此必炸。
%  [查4] 求解器承 0708-03 [查7–9]/0708-04 [查3] 纪律：定步长 ode4，步长 10 s
%        = env 记录步长（附录 E.3）。最快动态 τ_brg=C_brg/G_bw=112 s，h/τ=0.089；
%        显式稳定 h·λ_max=0.089 < 1（thermal_params 断言把关）。不连续块
%        （MinMax、FW 前值保持）统一 ZeroCross off。
%  [查5] 验收量值（oracle 实测）：B00（β≈0，3 轨）末轨 ΔT_brg=14.86 K ∈
%        [2,20]『数K~十几K』带，ΔT_bat=8.32 K；温度谷滞后本影段 +1110 s
%        （≈1.3×τ_whl=846 s，物理滞后而非同相）；B82（β≈82°，零地影）对照
%        末轨 ΔT_brg=1.04 K ≤ 0.30×B00。物理参数 ±20% 摄动 12/12 组存活。
%  [查6] 初值标定：t0_* 由 oracle --calibrate 按『B00 周期映射不动点』迭代
%        6 轮收敛（轨均漂移 0.002 K/轨），3 轨夹具内即为准周期解；B82 场景
%        初值改用解析平衡（selftest T4 同法）——量物理摆幅而非初值瞬态。
%  [查7] 驱动同构：sun/r 用 FW Interpolate on（= oracle 线性插值）、flag 用
%        Interpolate off（= 前值保持）、OutputAfterFinalValue 持端值；
%        selftest 以 'StartTime' 对齐 env.t(1)（B82 夹具起点 20 s 非零）。
%
% 用法（仓库根目录 rul-space/ 下）：
%   >> addpath('sim/model'); build_thermal_net
% 随后跑验收：
%   >> thermal_selftest

mdl     = 'thermal_net_dev';
fprintf('[build_thermal_net] 版本 v1.0（4 节点集总；定步长 ode4 @10s，同 oracle 积分器）\n');
here    = fileparts(mfilename('fullpath'));      % 期望位于 sim/model/
slxPath = fullfile(here, [mdl '.slx']);
if bdIsLoaded(mdl), close_system(mdl, 0); end
if exist(slxPath, 'file'), delete(slxPath); end

% ---------- 0. 参数装载（同 bat_params 模式：脚本在 path 上即可） ----------
addpath(here);
thermal_params();

% ---------- 1. 新建模型与求解器配置 ----------
% 【为何定步长 ode4】承 0708-03 [查7–9]：本模型含 MinMax(max(0,·)) 与 flag
%   前值保持两处不连续；定步长按固定步进跨越、不做过零定位。10 s 步长对最快
%   动态 τ_brg=112 s 仍有 11× 余量，且与验证 oracle 的 RK4 逐位同构。
new_system(mdl);
set_param(mdl, ...
    'SolverType','Fixed-step', 'Solver','ode4', ...            % 定步长 RK4 = oracle 同款
    'FixedStep','thm.test_dt_s', ...                           % 10 s（见 [查4]）
    'StopTime','thm.test_tend_s', ...                          % 兜底；selftest 按 env 实长覆写
    'SaveFormat','Dataset', ...
    'ReturnWorkspaceOutputs','on', 'ReturnWorkspaceOutputsName','out', ...
    'PreLoadFcn', ['try, thermal_params; catch, ' ...
    'warning(''thermal_params.m not on path: addpath sim/model first''); end']);

% ---------- 2. ① thermal_net 子系统（本任务交付物） ----------
tn = [mdl '/thermal_net'];
add_block('built-in/Subsystem', tn, 'Position',[330 80 500 420]);
build_net_inside(tn);

% ---------- 3. ② 验收 harness：env 三路驱动 + 内热常值 + 五路记录 ----------
add_block('simulink/Sources/From Workspace',[mdl '/fw_sun'], ...
    'VariableName','env_sun','SampleTime','0','Interpolate','on', ...
    'OutputAfterFinalValue','Holding final value', ...
    'Position',[60  90 150 120]);                              % ŝ 线性插值（[查7]）
add_block('simulink/Sources/From Workspace',[mdl '/fw_r'], ...
    'VariableName','env_r','SampleTime','0','Interpolate','on', ...
    'OutputAfterFinalValue','Holding final value', ...
    'Position',[60 150 150 180]);                              % r 线性插值
add_block('simulink/Sources/From Workspace',[mdl '/fw_flag'], ...
    'VariableName','env_flag','SampleTime','0','Interpolate','off', ...
    'OutputAfterFinalValue','Holding final value', ...
    'ZeroCross','off', ...                                     % 前值保持 + 关过零（[查4]）
    'Position',[60 210 150 240]);
add_block('simulink/Sources/Constant',[mdl '/src_q_rw_motor'], ...
    'Value','thm.q_rw_motor_w','Position',[60 280 150 310]);   % 0711-01 换 i²R 实时信号
add_block('simulink/Sources/Constant',[mdl '/src_q_rw_fric'], ...
    'Value','thm.q_rw_fric_w','Position',[60 340 150 370]);    % 0711-01 换 Mf·ω 实时信号
add_block('simulink/Sources/Constant',[mdl '/src_q_bat'], ...
    'Value','thm.q_bat_w','Position',[60 400 150 430]);        % 0711-01 换 power_ecm/4

tw = {'log_brg', 'thm_brg_c',    [640  90];
      'log_bat', 'thm_bat_c',    [640 160];
      'log_whl', 'thm_whl_c',    [640 230];
      'log_str', 'thm_str_c',    [640 300];
      'log_qsol','thm_qsolar_w', [640 370]};
for k = 1:size(tw,1)
    p = tw{k,3};
    add_block('simulink/Sinks/To Workspace',[mdl '/' tw{k,1}], ...
        'VariableName',tw{k,2},'SaveFormat','Timeseries', ...
        'Position',[p p+[110 30]]);
end

add_line(mdl,'fw_sun/1',        'thermal_net/1','autorouting','on');
add_line(mdl,'fw_r/1',          'thermal_net/2','autorouting','on');
add_line(mdl,'fw_flag/1',       'thermal_net/3','autorouting','on');
add_line(mdl,'src_q_rw_motor/1','thermal_net/4','autorouting','on');
add_line(mdl,'src_q_rw_fric/1', 'thermal_net/5','autorouting','on');
add_line(mdl,'src_q_bat/1',     'thermal_net/6','autorouting','on');
add_line(mdl,'thermal_net/1','log_brg/1', 'autorouting','on');
add_line(mdl,'thermal_net/2','log_bat/1', 'autorouting','on');
add_line(mdl,'thermal_net/3','log_whl/1', 'autorouting','on');
add_line(mdl,'thermal_net/4','log_str/1', 'autorouting','on');
add_line(mdl,'thermal_net/5','log_qsol/1','autorouting','on');

% ---------- 4. 同步编译校验 + 存盘（与 build_power_ecm 同法） ----------
feval(mdl, [], [], [], 'compile');   % 接口/命名/维度/参数问题在此同步报错
feval(mdl, [], [], [], 'term');
save_system(mdl, slxPath);
fprintf('[OK] 已生成 %s（compile/term 校验通过）\n', slxPath);
fprintf('     下一步验收：>> thermal_selftest\n');
end

% ======================================================================
function build_net_inside(tn)
% thermal_net 内部：env + 内热 → 热源/传导/辐射 → 四节点温度
% 端口契约（0711-01 整星集成按此接线；拟按 §11 流程登记为 interfaces.md 附录 L）：
%   In1  sun_eci            太阳方向单位矢量（ECI，3 维）← env.sun_eci_x/y/z
%   In2  r_eci_km           卫星 ECI 位置 [km]（3 维）  ← env.r_eci_*_km
%   In3  eclipse_flag       0 日照 / 1 半影 / 2 本影     ← env.eclipse_flag
%   In4  q_rw_motor_w       电机铜损 [W]（0711-01: rw_assembly 侧 i²R）
%   In5  q_rw_fric_w        轴承摩擦热 [W]（0711-01: Mf·ω，rpm→rad/s 换算）
%   In6  q_bat_w            电池产热 [W]（0711-01: power_ecm Out4 q_gen_w，K.2）
%   Out1 rw_bearing_temp_c  → 遥测 rw.bearing_temp_c（§6.5；0710-02 摩擦 LUT 温度轴）
%   Out2 bat_temp_c         → 遥测 bat.temp_c（§6.5）+ power_ecm In2 拆桩（K.2）
%   Out3 whl_temp_c         轮体温度诊断口（模型内信号，不入 §6.5/§5）
%   Out4 str_temp_c         结构板温度诊断口（同上）
%   Out5 q_solar_w          太阳吸热诊断口（同上；selftest T7 逐样本核对用）

add_block('simulink/Sources/In1',[tn '/sun_eci'],      'Position',[20  33 50  47]);
add_block('simulink/Sources/In1',[tn '/r_eci_km'],     'Position',[20  93 50 107]);
add_block('simulink/Sources/In1',[tn '/eclipse_flag'], 'Position',[20 153 50 167]);
add_block('simulink/Sources/In1',[tn '/q_rw_motor_w'], 'Position',[20 573 50 587]);
add_block('simulink/Sources/In1',[tn '/q_rw_fric_w'],  'Position',[20 693 50 707]);
add_block('simulink/Sources/In1',[tn '/q_bat_w'],      'Position',[20 813 50 827]);

% —— 热源链 q_solar = illum(flag)·( q_track + q_zen·max(0, ŝ·r̂) ) ——
add_block('simulink/Math Operations/Dot Product',[tn '/dot_sr'], ...
    'Position',[110 30 140 60]);                          % ŝ·r
add_block('simulink/Math Operations/Dot Product',[tn '/dot_rr'], ...
    'Position',[110 90 140 120]);                         % r·r = |r|²
add_block('simulink/Math Operations/Sqrt',[tn '/sqrt_r'], ...
    'Position',[170 90 200 120]);                         % |r|
add_block('simulink/Math Operations/Divide',[tn '/div_cos'], ...
    'Inputs','*/','Position',[230 35 260 75]);            % (ŝ·r)/|r| = ŝ·r̂
add_block('simulink/Sources/Constant',[tn '/const_zero'], ...
    'Value','0','Position',[230 110 260 140]);
add_block('simulink/Math Operations/MinMax',[tn '/max_cos'], ...
    'Function','max','Inputs','2','ZeroCross','off', ...  % max(0, ŝ·r̂)（[查4]）
    'Position',[300 55 330 95]);
add_block('simulink/Lookup Tables/1-D Lookup Table',[tn '/lut_illum'], ...
    'Table','thm.illum','BreakpointsForDimension1','thm.flag_bp', ...
    'InterpMethod','Linear point-slope','ExtrapMethod','Clip', ...
    'Position',[110 145 170 185]);                        % 地影开关（整值上恰取 1/0.5/0）
add_block('simulink/Math Operations/Gain',[tn '/g_qzen'], ...
    'Gain','thm.q_zen_w','Position',[370 60 420 90]);
add_block('simulink/Sources/Constant',[tn '/const_qtrack'], ...
    'Value','thm.q_track_w','Position',[370 10 420 40]);
add_block('simulink/Math Operations/Sum',[tn '/sum_qfull'], ...
    'Inputs','++','Position',[450 35 470 55]);            % q_track + q_zen·cos⁺
add_block('simulink/Math Operations/Product',[tn '/prod_qsol'], ...
    'Inputs','2','Position',[510 90 540 130]);            % × illum

% —— 传导流（各算一次，双向带符号复用）——
add_block('simulink/Math Operations/Sum',[tn '/sum_dws'], ...
    'Inputs','+-','Position',[640 460 660 480]);          % T_whl − T_str
add_block('simulink/Math Operations/Gain',[tn '/g_ws'], ...
    'Gain','thm.g_ws_w_k','Position',[690 455 740 485]);
add_block('simulink/Math Operations/Sum',[tn '/sum_dbw'], ...
    'Inputs','+-','Position',[640 530 660 550]);          % T_brg − T_whl
add_block('simulink/Math Operations/Gain',[tn '/g_bw'], ...
    'Gain','thm.g_bw_w_k','Position',[690 525 740 555]);
add_block('simulink/Math Operations/Sum',[tn '/sum_dbs'], ...
    'Inputs','+-','Position',[640 600 660 620]);          % T_bat − T_str
add_block('simulink/Math Operations/Gain',[tn '/g_bs'], ...
    'Gain','thm.g_bs_w_k','Position',[690 595 740 625]);

% —— 结构板辐射 q_rad = εσA·(T_str⁴ − T_space⁴) ——
add_block('simulink/Math Operations/Math Function',[tn '/sq_t2'], ...
    'Operator','square','Position',[110 240 150 270]);
add_block('simulink/Math Operations/Math Function',[tn '/sq_t4'], ...
    'Operator','square','Position',[180 240 220 270]);
add_block('simulink/Sources/Constant',[tn '/const_tspace4'], ...
    'Value','thm.tspace4_k4','Position',[180 300 240 330]);
add_block('simulink/Math Operations/Sum',[tn '/sum_rad'], ...
    'Inputs','+-','Position',[270 250 290 270]);
add_block('simulink/Math Operations/Gain',[tn '/g_rad'], ...
    'Gain','thm.gr_rad_w_k4','Position',[320 245 370 275]);

% —— 结构板节点：q_solar + q_earth + f_ws + f_bs − q_rad ——
add_block('simulink/Sources/Constant',[tn '/const_qearth'], ...
    'Value','thm.q_earth_w','Position',[510 160 570 190]);
add_block('simulink/Math Operations/Sum',[tn '/sum_str'], ...
    'Inputs','++++-','Position',[620 100 640 180]);
add_block('simulink/Math Operations/Gain',[tn '/g_invCstr'], ...
    'Gain','1/thm.c_str_j_k','Position',[680 125 730 155]);
add_block('simulink/Continuous/Integrator',[tn '/int_str'], ...
    'InitialCondition','thm.t0_str_k','Position',[770 125 800 155]);

% —— 轮体节点：q_motor − f_ws + f_bw ——
add_block('simulink/Math Operations/Sum',[tn '/sum_whl'], ...
    'Inputs','+-+','Position',[620 560 640 610]);
add_block('simulink/Math Operations/Gain',[tn '/g_invCwhl'], ...
    'Gain','1/thm.c_whl_j_k','Position',[770 570 820 600]);
add_block('simulink/Continuous/Integrator',[tn '/int_whl'], ...
    'InitialCondition','thm.t0_whl_k','Position',[860 570 890 600]);

% —— 轴承节点：q_fric − f_bw ——
add_block('simulink/Math Operations/Sum',[tn '/sum_brg'], ...
    'Inputs','+-','Position',[620 690 640 720]);
add_block('simulink/Math Operations/Gain',[tn '/g_invCbrg'], ...
    'Gain','1/thm.c_brg_j_k','Position',[770 690 820 720]);
add_block('simulink/Continuous/Integrator',[tn '/int_brg'], ...
    'InitialCondition','thm.t0_brg_k','Position',[860 690 890 720]);

% —— 电池节点：q_bat − f_bs ——
add_block('simulink/Math Operations/Sum',[tn '/sum_bat'], ...
    'Inputs','+-','Position',[620 810 640 840]);
add_block('simulink/Math Operations/Gain',[tn '/g_invCbat'], ...
    'Gain','1/thm.c_bat_j_k','Position',[770 810 820 840]);
add_block('simulink/Continuous/Integrator',[tn '/int_bat'], ...
    'InitialCondition','thm.t0_bat_k','Position',[860 810 890 840]);

% —— K → °C 出口（共享一个 273.15 常量）——
add_block('simulink/Sources/Constant',[tn '/const_c0'], ...
    'Value','thm.c0_k','Position',[930 460 990 490]);
add_block('simulink/Math Operations/Sum',[tn '/sum_brg_c'], ...
    'Inputs','+-','Position',[1030 690 1050 720]);
add_block('simulink/Math Operations/Sum',[tn '/sum_bat_c'], ...
    'Inputs','+-','Position',[1030 810 1050 840]);
add_block('simulink/Math Operations/Sum',[tn '/sum_whl_c'], ...
    'Inputs','+-','Position',[1030 570 1050 600]);
add_block('simulink/Math Operations/Sum',[tn '/sum_str_c'], ...
    'Inputs','+-','Position',[1030 125 1050 155]);

% —— 输出端口 ——
add_block('simulink/Sinks/Out1',[tn '/rw_bearing_temp_c'],'Position',[1100 698 1130 712]);
add_block('simulink/Sinks/Out1',[tn '/bat_temp_c'],       'Position',[1100 818 1130 832]);
add_block('simulink/Sinks/Out1',[tn '/whl_temp_c'],       'Position',[1100 578 1130 592]);
add_block('simulink/Sinks/Out1',[tn '/str_temp_c'],       'Position',[1100 133 1130 147]);
add_block('simulink/Sinks/Out1',[tn '/q_solar_w'],        'Position',[1100  38 1130  52]);

% —— 接线（同一输出口多条 add_line 自动生成分支）——
add_line(tn,'sun_eci/1','dot_sr/1',      'autorouting','on');
add_line(tn,'r_eci_km/1','dot_sr/2',     'autorouting','on');
add_line(tn,'r_eci_km/1','dot_rr/1',     'autorouting','on');
add_line(tn,'r_eci_km/1','dot_rr/2',     'autorouting','on');
add_line(tn,'dot_rr/1','sqrt_r/1',       'autorouting','on');
add_line(tn,'dot_sr/1','div_cos/1',      'autorouting','on');
add_line(tn,'sqrt_r/1','div_cos/2',      'autorouting','on');
add_line(tn,'div_cos/1','max_cos/1',     'autorouting','on');
add_line(tn,'const_zero/1','max_cos/2',  'autorouting','on');
add_line(tn,'eclipse_flag/1','lut_illum/1','autorouting','on');
add_line(tn,'max_cos/1','g_qzen/1',      'autorouting','on');
add_line(tn,'const_qtrack/1','sum_qfull/1','autorouting','on');
add_line(tn,'g_qzen/1','sum_qfull/2',    'autorouting','on');
add_line(tn,'lut_illum/1','prod_qsol/1', 'autorouting','on');
add_line(tn,'sum_qfull/1','prod_qsol/2', 'autorouting','on');
add_line(tn,'prod_qsol/1','sum_str/1',   'autorouting','on');   % +q_solar
add_line(tn,'prod_qsol/1','q_solar_w/1', 'autorouting','on');   % 诊断口
add_line(tn,'const_qearth/1','sum_str/2','autorouting','on');   % +q_earth

add_line(tn,'int_whl/1','sum_dws/1','autorouting','on');
add_line(tn,'int_str/1','sum_dws/2','autorouting','on');
add_line(tn,'sum_dws/1','g_ws/1',   'autorouting','on');
add_line(tn,'int_brg/1','sum_dbw/1','autorouting','on');
add_line(tn,'int_whl/1','sum_dbw/2','autorouting','on');
add_line(tn,'sum_dbw/1','g_bw/1',   'autorouting','on');
add_line(tn,'int_bat/1','sum_dbs/1','autorouting','on');
add_line(tn,'int_str/1','sum_dbs/2','autorouting','on');
add_line(tn,'sum_dbs/1','g_bs/1',   'autorouting','on');

add_line(tn,'int_str/1','sq_t2/1',        'autorouting','on');
add_line(tn,'sq_t2/1','sq_t4/1',          'autorouting','on');
add_line(tn,'sq_t4/1','sum_rad/1',        'autorouting','on');
add_line(tn,'const_tspace4/1','sum_rad/2','autorouting','on');
add_line(tn,'sum_rad/1','g_rad/1',        'autorouting','on');

add_line(tn,'g_ws/1','sum_str/3', 'autorouting','on');          % +f_ws
add_line(tn,'g_bs/1','sum_str/4', 'autorouting','on');          % +f_bs
add_line(tn,'g_rad/1','sum_str/5','autorouting','on');          % −q_rad
add_line(tn,'sum_str/1','g_invCstr/1','autorouting','on');
add_line(tn,'g_invCstr/1','int_str/1','autorouting','on');

add_line(tn,'q_rw_motor_w/1','sum_whl/1','autorouting','on');   % +q_motor
add_line(tn,'g_ws/1','sum_whl/2','autorouting','on');           % −f_ws
add_line(tn,'g_bw/1','sum_whl/3','autorouting','on');           % +f_bw
