add_line(tn,'g_invCwhl/1','int_whl/1','autorouting','on');

add_line(tn,'q_rw_fric_w/1','sum_brg/1','autorouting','on');    % +q_fric
add_line(tn,'g_bw/1','sum_brg/2','autorouting','on');           % −f_bw
add_line(tn,'sum_brg/1','g_invCbrg/1','autorouting','on');
add_line(tn,'g_invCbrg/1','int_brg/1','autorouting','on');

add_line(tn,'q_bat_w/1','sum_bat/1','autorouting','on');        % +q_bat
add_line(tn,'g_bs/1','sum_bat/2','autorouting','on');           % −f_bs
add_line(tn,'sum_bat/1','g_invCbat/1','autorouting','on');
add_line(tn,'g_invCbat/1','int_bat/1','autorouting','on');

add_line(tn,'int_brg/1','sum_brg_c/1','autorouting','on');
add_line(tn,'const_c0/1','sum_brg_c/2','autorouting','on');
add_line(tn,'int_bat/1','sum_bat_c/1','autorouting','on');
add_line(tn,'const_c0/1','sum_bat_c/2','autorouting','on');
add_line(tn,'int_whl/1','sum_whl_c/1','autorouting','on');
add_line(tn,'const_c0/1','sum_whl_c/2','autorouting','on');
add_line(tn,'int_str/1','sum_str_c/1','autorouting','on');
add_line(tn,'const_c0/1','sum_str_c/2','autorouting','on');
add_line(tn,'sum_brg_c/1','rw_bearing_temp_c/1','autorouting','on');
add_line(tn,'sum_bat_c/1','bat_temp_c/1',       'autorouting','on');
add_line(tn,'sum_whl_c/1','whl_temp_c/1',       'autorouting','on');
add_line(tn,'sum_str_c/1','str_temp_c/1',       'autorouting','on');
end

sim/model/run_dev_s001.m.text_utf8:
function outFile = run_dev_s001(line, simMode)
% RUN_DEV_S001  跑一条 dev 全寿命曲线并按 §simout 落盘（任务 0711-01 / 0711-02）
%
%   >> run_dev_s001 rwa                 % RWA_dev_S001（≈2.35e7 步，分钟级）
%   >> run_dev_s001 bat                 % BAT_dev_S001（≈4.3e8 步，加速模式约 0.5–1.5 h）
%   >> run_dev_s001('bat','rapid')      % 可选 normal / accelerator(默认) / rapid
%
% 流程（附录 AE 登记的口径逐条落地）：
%   ① 读 configs/sim/sample/<样本>.yaml（受限 YAML 子集：顶层 key: value +
%      两空格缩进的 overrides 带点键；本仓库样本卡由 0711-01 定稿，禁用
%      折行/列表等全功能 YAML —— 解析器见文末 read_flat_yaml）；
%   ② 备 env：优先 sim/gmat/out/env_LEO550_B30.mat（0708-02 正品），缺则用
%      fixtures 走 import_gmat 兜底再生（AE.6 限期豁免，provenance 记入
%      /meta/gmat_env_file）；取前 574 拍为 tile，按需周期延拓；负载律
%      i_chg 按实际 tile 旗历计数重算（AE.2，[查1]）；
%   ③ 备巡扫剖面 sim/model/out/adcs_profiles/adcs_profile_scan.mat，按日
%      周期延拓（首尾同值无缝，0711-01 前置件）；
%   ④ sat_params 带点键覆盖装参 → 覆写 5 路 From Workspace 驱动 → rng(seed)
%      （v1 模型无随机块，种子仅作复现指纹纪律）→ sim；
%   ⑤ labels 后处理（AE.4 权威口径：RWA 判据① V≥V_th 线性穿越 / 判据②
%      1 Hz 转速跟踪监督；BAT 逐轨 SOH 折线穿越 0.80）+ 事件窗构建（AE.3）；
%   ⑥ save_simout 落盘 data/raw/sim/dev/<样本>.mat（dev 路径命名 = AE.6
%      登记的限期例外，0714-01 收编 §5 正式路径时终止）；
%   ⑦ 对 fixtures/sat_dev_expect.json（oracle 单一事实源）做 A0–A6 机器
%      验收，全绿才算过。
%
% 版本：v1.0（0711-01/0711-02）

if nargin < 1, error('run_dev_s001:usage', '用法: run_dev_s001 rwa|bat'); end
line = validatestring(lower(char(line)), {'rwa','bat'});
if nargin < 2, simMode = 'accelerator'; end
simMode = validatestring(lower(char(simMode)), {'normal','accelerator','rapid'});

here = fileparts(mfilename('fullpath'));            % sim/model/
root = fileparts(fileparts(here));                  % 仓库根
addpath(here);
mdl = 'satellite_top';
P   = 5740;                                         % env tile 周期 [s]
if strcmp(line,'rwa'), sid = 'RWA_dev_S001'; else, sid = 'BAT_dev_S001'; end

% ---------- ① 样本卡 ----------
ymlPath = fullfile(root,'configs','sim','sample',[sid '.yaml']);
cfg = read_flat_yaml(ymlPath);
assert(strcmp(cfg.kv('sample_id'), sid), 'run_dev_s001:yaml', 'sample_id 不符');
seed = cfg.kv('seed');

% ---------- ② env：正品优先，fixtures 兜底（AE.6） ----------
envMat = fullfile(root,'sim','gmat','out','env_LEO550_B30.mat');
if exist(envMat, 'file')
    S = load(envMat, 'env'); env = S.env;
    gmat_prov = 'sim/gmat/out/env_LEO550_B30.mat';
else
    fprintf('[env] 正品缺失 → import_gmat 用 fixtures 兜底再生（AE.6 豁免）\n');
    addpath(fullfile(root,'sim','gmat'));
    env = import_gmat('LEO550_B30', ...
        'InDir',  fullfile(root,'sim','gmat','fixtures'), ...
        'OutDir', fullfile(root,'sim','gmat','out'));
    gmat_prov = 'sim/gmat/out/env_LEO550_B30.mat (fixtures->import_gmat 兜底, AE.6)';
end
assert(height(env) >= 574, 'run_dev_s001:env', 'env 不足一轨（574 拍）');
tt0 = double(env.t_s(1:574));
assert(max(abs(tt0 - (0:10:5730)')) < 1e-6, 'run_dev_s001:env', ...
    'env 前 574 拍非 0:10:5730 栅格');
tile.sun  = [double(env.sun_eci_x(1:574)), double(env.sun_eci_y(1:574)), ...
             double(env.sun_eci_z(1:574))];
tile.r    = [double(env.r_eci_x_km(1:574)), double(env.r_eci_y_km(1:574)), ...
             double(env.r_eci_z_km(1:574))];
tile.flag = round(double(env.eclipse_flag(1:574)));
tile.beta = double(env.beta_deg(1:574));
n0 = sum(tile.flag==0); n1 = sum(tile.flag==1); n2 = sum(tile.flag==2);
assert(n0 > 0 && n0+n1+n2 == 574, 'run_dev_s001:env', 'tile 旗历计数异常');
i_dis = 2.0;
i_chg = -i_dis * n2 / n0;                           % [查1] 逐轨净安时恒等 0
% 地影事件 tile 偏移（AE.3；1 基索引 i ↔ t=10·(i−1)）
trIdx  = find(diff(tile.flag) ~= 0) + 1;
in_off  = 10 * (trIdx(find(tile.flag(trIdx) ~= 0, 1)) - 1);
out_off = 10 * (trIdx(find(tile.flag(trIdx) == 0, 1)) - 1);

% ---------- 线口径 ----------
if strcmp(line,'rwa')
    stopT = cfg.kv('stop_time_s');
else
    stopT = cfg.kv('stop_time_max_s');
end

% ---------- ③ 巡扫剖面 ----------
profMat = fullfile(root,'sim','model','out','adcs_profiles','adcs_profile_scan.mat');
assert(exist(profMat,'file') == 2, 'run_dev_s001:prof', ...
    '缺 %s —— 先在仓库根运行 python sim/model/gen_adcs_profiles.py', profMat);
Sp = load(profMat); cprof = double(Sp.cmd_speed_rpm(:));
assert(numel(cprof) == 86401 && abs(cprof(1)-cprof(end)) < 1e-9, ...
    'run_dev_s001:prof', '剖面须 86401 拍且首尾同值（日拼接无缝）');

% ---------- ④ 模型就位（必须先于装参！）----------
% ensure/重建/首次 load 的 PreLoadFcn 都会**裸调 sat_params 把 base 重置默认**；
% 0711 真机教训：先装参后就位 → 重建洗掉 stop_time_s/aging_scale，BAT 假跑 1 轨。
% 顺序铁律：就位在前，override 装参最后落地，压住一切裸调。
ensure_sat_top_v3(here, mdl);
load_system(mdl);

% ---------- ⑤ 装参 + 驱动覆写 + 仿真 ----------
ov = cfg.ov;                                        % YAML overrides（带点键）
ov = [ov, {'sat.load_i_by_flag', [i_chg 0 i_dis], 'sat.stop_time_s', stopT}];
sat_params(ov{:});
sat = evalin('base','sat'); rw = evalin('base','rw'); bat = evalin('base','bat');

nrep = ceil((stopT + P) / P);
te   = (0:10:(nrep*574*10 - 10))';
assignin('base','env_sun',  fwstruct(te, repmat(tile.sun,  nrep, 1), 3));
assignin('base','env_r',    fwstruct(te, repmat(tile.r,    nrep, 1), 3));
assignin('base','env_flag', fwstruct(te, repmat(tile.flag, nrep, 1), 1));
assignin('base','env_beta', fwstruct(te, repmat(tile.beta, nrep, 1), 1));
nd = ceil((stopT + P) / 86400);
tp = (0:1:nd*86400)';
assignin('base','prof_cmd_rpm', fwstruct(tp, cprof(mod(tp,86400)+1), 1));
rng(seed);

try
    set_param(mdl, 'SimulationMode', simMode);
catch ME
    warning('run_dev_s001:mode', '%s 模式不可用（%s）→ 退回 normal', ...
        simMode, ME.message);
    set_param(mdl, 'SimulationMode', 'normal');
end
nStep = stopT / sat.fixed_step_s;
fprintf('[sim] %s | StopTime=%g s | 模式=%s | 定步长 %g s（约 %.2e 步）…\n', ...
    sid, stopT, get_param(mdl,'SimulationMode'), sat.fixed_step_s, nStep);
if nStep > 1e8
    fprintf(['[sim] 大步长长跑（BAT 全寿命）：单次 sim() 全程无进度打印，' ...
             '请以 CPU 占用判断是否在算（非 0 即正常推进），预计墙钟见教程墙钟表；' ...
             '已关满步 tout 记录（SaveTime=off），不再有 4.6GB 内存抖动。\n']);
end
assert_ov_alive(ov);   % 绝杀线：每个 override 此刻必须仍在 base（防装参顺序回归）
tic; out = sim(mdl); wall = toc;
fprintf('[sim] 完成，墙钟 %.1f s\n', wall);

% ---------- ⑤ 展平 + 后处理 ----------
[t01, tel] = flat_bus(out.get('telemetry_01hz'));
[~,  tru]  = flat_bus(out.get('truth_01hz'));
[t1,  tl1] = flat_bus(out.get('telemetry_1hz'));
N = numel(t01);
assert(abs(t01(1)) < 1e-9 && max(abs(diff(t01)-10)) < 1e-6, ...
    'run_dev_s001:grid', '0.1 Hz 主档非 10 s 栅格');
assert(max(abs(diff(t1)-1)) < 1e-6, 'run_dev_s001:grid', '1 Hz 精档非 1 s 栅格');
Tend = t01(end);

% —— labels（AE.4 权威口径）——
man  = jsondecode(read_text_utf8(fullfile(here,'fixtures','sat_dev_expect.json')));
lman = select_manifest_line(man, sid, rw.friction_plan);
if strcmp(line,'rwa')
    tf1 = first_crossing(t01, tru.rw_wear_volume_mm3, rw.v_th_mm3);   % 判据①
    cmd1 = cprof(mod(round(t1),86400)+1);                             % 判据②监督
    onset2 = speed_fail_onset(t1, tl1.rw_speed_rpm, cmd1, ...
        rw.spd_err_th_rpm, rw.fail_hold_s);
    if ~isempty(tf1) && (isempty(onset2) || tf1 <= onset2)
        tf = tf1; code = 1;
    elseif ~isempty(onset2)
        tf = onset2; code = 2;
    else
        tf = NaN; code = 0;
    end
    mf0 = tru.rw_friction_torque_nm(1);                               % [查7]/AE.4
    [hi, hi_raw_max, hi_fallback] = rwa_hi_components( ...
        tru.rw_wear_volume_mm3, tru.rw_friction_torque_nm, rw);
    critTxt = sprintf('%s；friction_fallback=%s，raw_max=%.4g', ...
        lman.failure.criterion_text, hi_fallback, hi_raw_max);
else
    stop_orbit = round(Tend / P);
    assert(abs(Tend - stop_orbit*P) < 1e-6, 'run_dev_s001:stop', ...
        'BAT 线须停在整轨结算步上（SOH 停机机构）');
    kx = [0; (1:stop_orbit)' * P];
    ky = [1; tru.bat_soh(1 + 574*(1:stop_orbit)')];
    tf = first_crossing(kx, 1 - ky, 1 - sat.bat_fail_soh);            % 折线穿越 0.80
    code = 11; mf0 = NaN;
    if isempty(tf)
        soh_end = ky(end); soh_min = min(ky);
        error('run_dev_s001:tf', ['BAT 线跑到 %d 轨（%.3e 步）SOH 仍未穿越 ' ...
            '%.3f：SOH 末值=%.4f、最低=%.4f、逐轨降幅=%.2e/轨。诊断：' ...
            '① 若 SOH≈1.000 几乎不动 → 老化结算未触发（查 aging_model_v1 ' ...
            '轨道脉冲/触发子系统，或 bat.aging_scale=%.0f 未到模型）；' ...
            '② 若 SOH 在降但太慢 → aging_scale 偏小或 LUT 吞吐口径不符。' ...
            '对照 oracle：aging_scale=200 应 155 轨降到 0.794。'], ...
            stop_orbit, Tend/sat.fixed_step_s, 1 - (1 - sat.bat_fail_soh), ...
            soh_end, soh_min, (1 - soh_min)/max(stop_orbit,1), bat.aging_scale);
    end
    hi = (1 - tru.bat_soh) / (1 - sat.bat_fail_soh);
    hi = max(hi, 0);
    critTxt = lman.failure.criterion_text;
end
fail  = int8(t01 >= tf);
rul_d = (tf - t01) / 86400;

% —— 事件窗（AE.3）——
ev = [];                                            % [code, t_e]
for k = 0:ceil(Tend/P)
    if in_off  + k*P <= Tend, ev = [ev; 1, in_off  + k*P]; end          %#ok<AGROW>
    if out_off + k*P <= Tend, ev = [ev; 2, out_off + k*P]; end          %#ok<AGROW>
end
if ~isnan(tf) && tf >= 0 && tf <= Tend, ev = [ev; 4, tf]; end
ev = sortrows(ev, 2);
K = size(ev,1);
widx = zeros(K,4); hi_t = []; hi_id = []; hi_rows = [];
for w = 1:K
    a = max(0, ev(w,2) - sat.win_halfwidth_s);
    b = min(Tend, ev(w,2) + sat.win_halfwidth_s);
    widx(w,:) = [w, ev(w,1), a, b];
    ss = (ceil(a - 1e-9):floor(b + 1e-9))';
    hi_t  = [hi_t;  ss];                                                %#ok<AGROW>
    hi_id = [hi_id; repmat(w, numel(ss), 1)];                           %#ok<AGROW>
    hi_rows = [hi_rows; round(ss) + 1];                                 %#ok<AGROW>
end
assert(all(hi_rows >= 1 & hi_rows <= numel(t1)), 'run_dev_s001:win', ...
    '事件窗样本越出 1 Hz 记录');

% ---------- 结构装配（§5 嵌套；按线过滤 AF.3） ----------
telemetry.t_days = t01 / 86400;
telemetry.orbit  = struct('eclipse_flag', tel.eclipse_flag, ...
                          'beta_deg',     tel.beta_deg);
telemetry_hi.t_s = hi_t;
telemetry_hi.window_id = hi_id;
telemetry_hi.windows_index = widx;
telemetry_hi.orbit = struct('eclipse_flag', tl1.eclipse_flag(hi_rows), ...
                            'beta_deg',     tl1.beta_deg(hi_rows));
truth.cycle_index = floor(t01 / P);
if strcmp(line,'rwa')
    telemetry.rw = struct('speed_rpm', tel.rw_speed_rpm, ...
        'motor_current_a', tel.rw_motor_current_a, ...
        'cmd_torque_nm',   tel.rw_cmd_torque_nm, ...
        'bearing_temp_c',  tel.rw_bearing_temp_c);
    telemetry_hi.rw = struct('speed_rpm', tl1.rw_speed_rpm(hi_rows), ...
        'motor_current_a', tl1.rw_motor_current_a(hi_rows), ...
        'cmd_torque_nm',   tl1.rw_cmd_torque_nm(hi_rows), ...
        'bearing_temp_c',  tl1.rw_bearing_temp_c(hi_rows));
    truth.rw = struct('friction_torque_nm', tru.rw_friction_torque_nm, ...
        'wear_volume_mm3', tru.rw_wear_volume_mm3, ...
        'lube_level',      tru.rw_lube_level);
else
    telemetry.bat = struct('voltage_v', tel.bat_voltage_v, ...
        'current_a', tel.bat_current_a, 'temp_c', tel.bat_temp_c, ...
        'soc', tel.bat_soc);
    telemetry_hi.bat = struct('voltage_v', tl1.bat_voltage_v(hi_rows), ...
        'current_a', tl1.bat_current_a(hi_rows), ...
        'temp_c',    tl1.bat_temp_c(hi_rows), ...
        'soc',       tl1.bat_soc(hi_rows));
    truth.bat = struct('soh', tru.bat_soh, 'lli', tru.bat_lli, ...
        'lam', tru.bat_lam);
end
labels = struct('rul_days', rul_d, 'hi', hi, 'fail', fail, 'attrs', ...
    struct('failure_time_days', tf/86400, 'failure_mode_code', code, ...
           'criterion_text', critTxt));

% —— /meta ——
meta = struct( ...
    'sample_id', sid, ...
    'config_yaml', cfg.raw, ...
    'seed', seed, ...
    'sim_model_version', sat.version, ...
    'lut_versions', read_text_utf8(fullfile(root,'sim','lut','lut_manifest.json')), ...
    'gmat_env_file', gmat_prov, ...
    'matlab_ver', version, ...
    'created_utc', char(datetime('now','TimeZone','UTC', ...
        'Format','yyyy-MM-dd''T''HH:mm:ss''Z''')), ...
    'schema_version', sat.schema_version);

outFile = fullfile(root,'data','raw','sim','dev',[sid '.mat']);   % AE.6 限期例外
save_simout(outFile, telemetry, telemetry_hi, truth, labels, meta);

% ---------- ⑦ A0–A6 机器验收（对 oracle 锚点，AE.5 容差） ----------
bad = {};

% A0 样本卡 overrides ↔ manifest overrides 一致
mo = lman.overrides; mk = fieldnames(mo); okA0 = true;
for k = 1:numel(mk)
    key = fix_dot_key(mk{k});
    j = find(strcmp(cfg.ov(1:2:end), key));
    okA0 = okA0 && ~isempty(j) && isequal_num(cfg.ov{2*j}, mo.(mk{k}));
end
ck(okA0 && numel(cfg.ov)/2 == numel(mk), 'A0', 'YAML overrides = manifest overrides');

% A1 计数
if strcmp(line,'rwa')
    ck(N == lman.n_01hz, 'A1', sprintf('N=%d (期望 %d)', N, lman.n_01hz));
else
    so = round(Tend / P);
    ck(abs(so - lman.stop_orbit.value) <= lman.stop_orbit.tol, 'A1a', ...
        sprintf('stop_orbit=%d (期望 %d±%d)', so, lman.stop_orbit.value, ...
        lman.stop_orbit.tol));
    ck(N == so*574 + 1, 'A1b', sprintf('N=%d = stop_orbit·574+1', N));
end

% A2 失效
ck(abs(tf - lman.failure.time_s) <= lman.failure.rtol*lman.failure.time_s ...
    && code == lman.failure.mode_code, 'A2', ...
    sprintf('Tf=%.1f s (期望 %.1f±%g%%) code=%d', tf, lman.failure.time_s, ...
    100*lman.failure.rtol, code));
if strcmp(line,'rwa')
    ck(abs(mf0 - lman.mf0_nm.value) <= lman.mf0_nm.rtol*lman.mf0_nm.value, ...
        'A2b', sprintf('Mf0=%.6g (期望 %.6g)', mf0, lman.mf0_nm.value));
end

% A3 锚点（rtol/atol 任一满足即过；无容差项跳过）
if isfield(lman,'anchors')
    an = lman.anchors; if ~iscell(an), an = num2cell(an); end
    for k = 1:numel(an)
        a = an{k};
        got = resolve_ch(a.ch, a.t_s, t01, tel, tru);
        if isempty(got) || (~isfield(a,'rtol') && ~isfield(a,'atol')), continue; end
        ok = (isfield(a,'rtol') && abs(got-a.value) <= a.rtol*abs(a.value)) || ...
             (isfield(a,'atol') && abs(got-a.value) <= a.atol);
        ck(ok, 'A3', sprintf('%s: %.6g (期望 %.6g)', a.name, got, a.value));
    end
end

% A4 值域
rg = lman.ranges; rk = fieldnames(rg);
for k = 1:numel(rk)
    r = rg.(rk{k});
    switch rk{k}
        case 'T_brg_c', x = tel.rw_bearing_temp_c;
        case 'v_bat_v', x = tel.bat_voltage_v;
        case 'T_bat_c', x = tel.bat_temp_c;
        case 'soc',     x = tel.bat_soc;
        otherwise, continue
    end
    ck(abs(min(x)-r.min) <= r.atol && abs(max(x)-r.max) <= r.atol, 'A4', ...
        sprintf('%s∈[%.4g,%.4g] (期望 [%.4g,%.4g]±%g)', rk{k}, min(x), max(x), ...
        r.min, r.max, r.atol));
end

% A5 事件窗 + BAT 轨 1 账单
if strcmp(line,'rwa')
    ck(K == lman.windows_k, 'A5', sprintf('K=%d (期望 %d)', K, lman.windows_k));
else
    ck(K == 2*round(Tend/P) + 1, 'A5a', sprintf('K=%d = 2·stop+1', K));
    ob = lman.orbit1_bill;
    dah  = sum(abs(tl1.bat_current_a(1:P))) / 3600;   % 1 Hz 左矩形=分段常值精确
    dod  = max(tl1.bat_soc(1:P+1)) - min(tl1.bat_soc(1:P+1));
    cbar = dah*3600 / (P*bat.q0_ah);
    tbar = trapz(t1(1:P+1), tl1.bat_temp_c(1:P+1)) / P;
    soh1 = tru.bat_soh(575);
    ck(abs(dah -ob.dah_ah.value) <= ob.dah_ah.rtol*ob.dah_ah.value, 'A5b', ...
        sprintf('dah=%.5f Ah', dah));
    ck(abs(dod -ob.dod.value)   <= ob.dod.atol,  'A5c', sprintf('DOD=%.4f', dod));
    ck(abs(cbar-ob.cbar.value)  <= ob.cbar.rtol*ob.cbar.value, 'A5d', ...
        sprintf('c̄=%.5f', cbar));
    ck(abs(tbar-ob.tbar_c.value)<= ob.tbar_c.atol,'A5e', sprintf('T̄=%.2f ℃', tbar));
    ck(abs(soh1-ob.soh_after.value) <= ob.soh_after.atol, 'A5f', ...
        sprintf('soh(轨1)=%.5f', soh1));
    sp = lman.soh_spots; if ~iscell(sp), sp = num2cell(sp); end
    for k = 1:numel(sp)
        s = sp{k}; j = 1 + 574*s.orbit;
        if j <= N
            ck(abs(tru.bat_soh(j)-s.value) <= s.atol, 'A5g', ...
                sprintf('soh@轨%d=%.5f (期望 %.5f)', s.orbit, tru.bat_soh(j), s.value));
        end
    end
end
M_exp = lman.hi_samples_m;
if strcmp(line,'rwa') || round(Tend/P) == lman.stop_orbit.value
    ck(abs(numel(hi_t) - M_exp.value) <= M_exp.tol, 'A5h', ...
        sprintf('M=%d (期望 %d±%d)', numel(hi_t), M_exp.value, M_exp.tol));
else
    ck(true, 'A5h', sprintf(['M=%d（stop_orbit=%d 落在 ±%d 带内但 ≠ oracle 名义值，' ...
        '跳过 manifest 对表；结构由 V5d 逐窗核）'], numel(hi_t), ...
        round(Tend/P), lman.stop_orbit.tol));
end

% A6 线内不变式
if strcmp(line,'rwa')
    if lman.failure.mode_code == 2
        early2 = t1 <= 2*P;
        err2_early = max(abs(cmd1(early2) - tl1.rw_speed_rpm(early2)));
        ck(~isempty(onset2), 'A6a', '判据② 按 plan A 如期触发');
        ck(~isempty(onset2) && ...
            abs(onset2 - tf) <= 0.5 * (t1(2) - t1(1)), 'A6d', ...
            sprintf('判据② onset=%.1f s 与 Tf=%.1f s 对齐', onset2, tf));
        ck(err2_early < rw.spd_err_th_rpm, 'A6e', ...
            sprintf('前两轨 max|cmd−ω|=%.2f rpm (<%g)', ...
            err2_early, rw.spd_err_th_rpm));
    elseif lman.failure.mode_code == 1
        err2 = max(abs(cmd1 - tl1.rw_speed_rpm));
        ck(err2 <= lman.checks.spd_track_max_err_rpm, 'A6a', ...
            sprintf('max|cmd−ω|=%.2f rpm (≤%g)', ...
            err2, lman.checks.spd_track_max_err_rpm));
        ck(isempty(onset2), 'A6d', '判据② 全程未触发（plan B）');
    else
        ck(false, 'A6a', sprintf('不支持的 RWA failure_mode_code=%d', ...
            lman.failure.mode_code));
    end
    ck(min(tru.bat_soh) >= lman.checks.soh_min, 'A6b', ...
        sprintf('soh_min=%.5f (≥%g，未滤前记录)', min(tru.bat_soh), lman.checks.soh_min));
    hitf = interp1(t01, hi, tf);
    ck(abs(hitf - lman.checks.hi_at_tf.value) <= lman.checks.hi_at_tf.atol, ...
        'A6c', sprintf('hi(Tf)=%.4f', hitf));
else
    so = round(Tend/P);
    soh_orb = tru.bat_soh(1 + 574*(1:so)');
    ck(all(diff(soh_orb) <= 1e-12), 'A6a', 'SOH 逐轨单调不增');
    ck(tru.rw_wear_volume_mm3(end) <= lman.checks.rw_wear_end_max_mm3, 'A6b', ...
        sprintf('名义磨损末值=%.4f mm³ (≤%g)', tru.rw_wear_volume_mm3(end), ...
        lman.checks.rw_wear_end_max_mm3));
end

if isempty(bad)
    fprintf(['[OK] %s 全寿命曲线通过 A 组机器验收（oracle 锚点全绿）\n' ...
        '     产物: %s\n     下一步: python scripts/validate_simout.py %s\n'], ...
        sid, outFile, outFile);
else
    error('run_dev_s001:accept', '%s 验收失败项: %s', sid, strjoin(bad, ', '));
end

    function ck(ok, tag, msg)   % 嵌套：与父函数共享 bad（规范尾置）
        fprintf('  [%s] %s  %s\n', tern(ok,'PASS','FAIL'), tag, msg);
        if ~ok, bad{end+1} = tag; end
    end
end

