function [t, s] = flat_bus(x)
% To Workspace(SaveFormat=Timeseries) 记录总线 → struct(元素名→timeseries)。
% 兼容裸 timeseries（非总线）与 struct-of-timeseries 两种形态（承 run_dev0.m）。
if isa(x, 'timeseries')
    t = x.Time(:); s = struct('y', double(x.Data)); return;
end
assert(isstruct(x), 'flat_bus:type', '未知记录形态 %s', class(x));
fn = fieldnames(x);
% 时间轴取「最长通道」为准：Constant 占位块（如 src_lam，SampleTime=inf）只记
% 1 个采样点，若用它定 t 会误伤动态通道；仿真栅格 = 动态通道的公共最长时间向量。
t = []; nmax = 0;
for k = 1:numel(fn)
    ts = x.(fn{k});
    if isa(ts, 'timeseries') && numel(ts.Time) > nmax
        nmax = numel(ts.Time); t = ts.Time(:);
    end
end
assert(~isempty(t), 'flat_bus:notime', '总线内无 timeseries 通道');
s = struct();
for k = 1:numel(fn)
    ts = x.(fn{k});
    if ~isa(ts, 'timeseries'), continue; end
    d = double(ts.Data); d = d(:);
    if numel(d) == numel(t)
        s.(fn{k}) = d;
    elseif numel(d) == 1
        s.(fn{k}) = repmat(d, numel(t), 1);   % 标量常量占位 → 广播到栅格（AE.2：lam≡0）
    else
        error('flat_bus:len', ['通道 %s 长度 %d 与时间轴 %d 不符' ...
            '（非标量常量，无法广播）'], fn{k}, numel(d), numel(t));
    end
end
end

function assert_ov_alive(ov)
% 覆盖存活断言（0711-2 教训）：装参后到 sim 前，任何环节（重建/PreLoadFcn/
% 手滑 clear）把 base 参数洗回默认都在这里被当场击毙，绝不带病假跑。
for k = 1:2:numel(ov)
    key = ov{k}; val = ov{k+1};
    d = strfind(key, '.');
    got = evalin('base', sprintf('%s.%s', key(1:d(1)-1), key(d(1)+1:end)));
    assert(isequal(size(got), size(val)) && max(abs(got(:) - val(:))) < 1e-9, ...
        'run_dev_s001:ov_dead', ...
        '覆盖 %s 未存活（base 现值 %s ≠ 卡值 %s）——装参顺序被破坏？', ...
        key, mat2str(got, 6), mat2str(val, 6));
end
end

function tf = first_crossing(t, y, th)
% y ≥ th 的首个线性插值穿越时刻；未穿越 → []（同 oracle first_crossing）
j = find(y >= th, 1);
if isempty(j), tf = []; return; end
if j == 1, tf = t(1); return; end
tf = t(j-1) + (th - y(j-1)) / (y(j) - y(j-1)) * (t(j) - t(j-1));
end

function onset = speed_fail_onset(t, w, wcmd, th_rpm, hold_s)
% 判据②：|ω_cmd−ω| > 阈 连续 hold_s 的首个满足时刻（窗末；同 oracle）
bad = abs(wcmd(:) - w(:)) > th_rpm;
dt = t(2) - t(1);
need = round(hold_s / dt);
run = 0; onset = [];
for k = 1:numel(bad)
    if bad(k), run = run + 1; else, run = 0; end
    if run >= need, onset = t(k); return; end
end
end

function got = resolve_ch(ch, t_s, t01, tel, tru)
% manifest 锚点通道名 → 已展平数组的取值；未知/信息位通道返回 []
j = round(t_s/10) + 1;
switch ch
    case 'telemetry.rw.speed_rpm',        x = tel.rw_speed_rpm;
    case 'telemetry.rw.motor_current_a',  x = tel.rw_motor_current_a;
    case 'telemetry.rw.cmd_torque_nm',    x = tel.rw_cmd_torque_nm;
    case 'telemetry.rw.bearing_temp_c',   x = tel.rw_bearing_temp_c;
    case 'telemetry.bat.voltage_v',       x = tel.bat_voltage_v;
    case 'telemetry.bat.current_a',       x = tel.bat_current_a;
    case 'telemetry.bat.temp_c',          x = tel.bat_temp_c;
    case 'telemetry.bat.soc',             x = tel.bat_soc;
    case 'truth.rw.friction_torque_nm',   x = tru.rw_friction_torque_nm;
    case 'truth.rw.wear_volume_mm3',      x = tru.rw_wear_volume_mm3;
    case 'truth.rw.lube_level',           x = tru.rw_lube_level;
    otherwise, got = []; return;
end
assert(j >= 1 && j <= numel(x) && abs(t01(j) - t_s) < 1e-6, ...
    'resolve_ch:idx', '锚点时刻 %g 不在 0.1 Hz 栅格上', t_s);
got = x(j);
end

