function cfg = read_flat_yaml(path)
% 受限 YAML 子集解析（AE 附注）：顶层 `key: value` + 两空格缩进的
% overrides 带点键；# 整行注释；数值自动转 double，其余保留字符串。
raw = read_text_utf8(path);
cfg.raw = raw;
cfg.ov = {};
kv = struct();
L = regexp(raw, '\r?\n', 'split');
inOv = false;
for i = 1:numel(L)
    ln = L{i};
    if isempty(strtrim(ln)) || startsWith(strtrim(ln), '#'), continue; end
    ind = startsWith(ln, '  ');
    ln2 = strtrim(ln);
    c = strfind(ln2, ':');
    assert(~isempty(c), 'read_flat_yaml:line', '第 %d 行缺冒号: %s', i, ln2);
    key = strtrim(ln2(1:c(1)-1));
    val = strtrim(ln2(c(1)+1:end));
    if strcmp(key, 'overrides') && isempty(val)
        inOv = true; continue;
    end
    if ~ind, inOv = false; end
    v = parse_scalar(val);
    if inOv && ind
        cfg.ov(end+1:end+2) = {key, v};
    else
        kv.(matlab.lang.makeValidName(key)) = v;
    end
end
cfg.kv = @(k) kv.(matlab.lang.makeValidName(k));
end

function v = parse_scalar(s)
if isempty(s), v = ''; return; end
if (startsWith(s,'"') && endsWith(s,'"')) || (startsWith(s,'''') && endsWith(s,''''))
    v = s(2:end-1); return;
end
d = str2double(s);
if ~isnan(d), v = d; else, v = s; end
end

% ----------------------------------------------------------------------
function y = orbit_block_median(x, beats)
% 逐轨(574 拍)块中位（0715-02：hi 摩擦支走趋势；块=连续 beats 拍，尾块允许
% 不满；块内取中位后铺回全块。与 oracle_satellite_top.orbit_block_median 同构）
y = zeros(size(x));
n = numel(x);
for k0 = 1:beats:n
    k1 = min(k0 + beats - 1, n);
    y(k0:k1) = median(x(k0:k1));
end
end

function [hi, hi_raw_max, fallback] = rwa_hi_components(V, mf, rw)
wear_hi = V / rw.v_th_mm3;
mf0 = mf(1);
mf_tr = orbit_block_median(mf, 574);
denominator = rw.mf_fail_nm - mf0;
fallback = 'none';
if isfinite(denominator) && denominator > 1e-6
    friction_hi = (mf_tr - mf0) / denominator;
    if any(~isfinite(friction_hi)) || friction_hi(1) >= 1
        friction_hi = zeros(size(mf_tr));
        fallback = 'initial_orbit_at_or_above_anchor';
    end
else
    friction_hi = zeros(size(mf_tr));
    fallback = 'nonpositive_friction_headroom';
end
raw_hi = max(wear_hi, friction_hi);
hi_raw_max = max(raw_hi);
hi = min(max(raw_hi, 0), 1.5);
end

