function sat_selftest()
% SAT_SELFTEST  整星集成 S0–S9 快档验收（任务 0711-01；目标 <10 min）
%
% 覆盖面（全寿命曲线与 §simout 终验收在 run_dev_s001 + validate_simout.py）：
%   S0 构建产物存在（缺则现场 build_satellite_top）
%   S1 sat_params 装参 + 编译桩齐全        S2 三条 Bus 元素数 10/6/3（AE.1）
%   S3 compile/term 同步校验                S4 两轨 smoke 仿真（真 env+真剖面）
%   S5 双档记录通道齐全 + 栅格/样本数        S6 物理符号带（负载律/电压/温度/跟踪）
%   S7 oracle 早期锚点（sat_dev_expect.json 中 t≤2 轨的 A3 子集）
%   S8 save_simout 结构冒烟（HDF5 面检：五顶层组 + labels 三属性 + meta_json）
%   S9 汇总
%
% 用法（仓库根目录）：
%   >> addpath('sim/model'); sat_selftest
%
% 版本：v1.0（0711-01）

here = fileparts(mfilename('fullpath'));
root = fileparts(fileparts(here));
addpath(here);
mdl = 'satellite_top'; P = 5740;
bad = {};

% ---------- S0 ----------
slx = fullfile(here, [mdl '.slx']);
ensure_sat_top_v3(here, mdl);   % 就位 + v3 指纹校验（v2 残留 → 强制重建）
ck(exist(slx,'file') == 2 || exist(slx,'file') == 4, 'S0', ...
    'satellite_top.slx 就位（v3 指纹：lut_iload + Bus 10/6/3）');

% ---------- S1 ----------
sat_params('rw.omega0_rpm', 1400, 'sat.stop_time_s', 2*P);
need = {'sat','rw','bat','thm','env_sun','env_r','env_flag','env_beta','prof_cmd_rpm'};
ok = true;
for k = 1:numel(need), ok = ok && evalin('base', sprintf('exist(''%s'',''var'')', need{k})) == 1; end
ck(ok, 'S1', '参数与编译桩齐全（sat/rw/bat/thm + 5 路驱动桩）');
sat = evalin('base','sat'); bat = evalin('base','bat'); rw = evalin('base','rw');
ck(bat.orbit_period_s == P && sat.orbit_period_s == P, 'S1b', ...
    sprintf('轨道周期统一 %g s（AE.2）', P));

% ---------- S2 ----------
satellite_buses();
nT = numel(evalin('base','TelemetryBus.Elements'));
nU = numel(evalin('base','TruthBus.Elements'));
nL = numel(evalin('base','LabelsBus.Elements'));
ck(nT == 10 && nU == 6 && nL == 3, 'S2', ...
    sprintf('Bus 元素数 %d/%d/%d（期望 10/6/3）', nT, nU, nL));

% ---------- S3 ----------
% compile/term 探针用 feval(model-as-function) 形式，MATLAB 不支持该形式在
% accelerator 模式下运行（build 出厂即置 accelerator）。编译校验本不需加速，
% 故临时切 normal 做探针再恢复；真正的加速仿真在 S4。
load_system(mdl);
mode0 = get_param(mdl, 'SimulationMode');
try
    set_param(mdl, 'SimulationMode', 'normal');
    feval(mdl, [], [], [], 'compile');
    feval(mdl, [], [], [], 'term');
    ck(true, 'S3', 'compile/term 通过（normal 探针，加速仿真见 S4）');
catch ME
    try, feval(mdl, [], [], [], 'term'); catch, end   % 异常时确保退出 compile 态
    ck(false, 'S3', ['compile 失败: ' ME.message]);
end
set_param(mdl, 'SimulationMode', mode0);

% ---------- S4 两轨 smoke（真 env + 真剖面） ----------
envMat = fullfile(root,'sim','gmat','out','env_LEO550_B30.mat');
if exist(envMat, 'file')
    S = load(envMat,'env'); env = S.env;
else
    addpath(fullfile(root,'sim','gmat'));
    env = import_gmat('LEO550_B30', ...
        'InDir',fullfile(root,'sim','gmat','fixtures'), ...
        'OutDir',fullfile(root,'sim','gmat','out'));
end
tile.sun  = [double(env.sun_eci_x(1:574)) double(env.sun_eci_y(1:574)) double(env.sun_eci_z(1:574))];
tile.r    = [double(env.r_eci_x_km(1:574)) double(env.r_eci_y_km(1:574)) double(env.r_eci_z_km(1:574))];
tile.flag = round(double(env.eclipse_flag(1:574)));
tile.beta = double(env.beta_deg(1:574));
n0 = sum(tile.flag==0); n2 = sum(tile.flag==2);
i_dis = sat.i_dis_a; i_chg = -i_dis*n2/n0;
sat_params('rw.omega0_rpm',1400, 'sat.stop_time_s',2*P, ...
    'sat.load_i_by_flag',[i_chg 0 i_dis]);
nrep = 3; te = (0:10:(nrep*574*10-10))';
assignin('base','env_sun',  fws(te, repmat(tile.sun, nrep,1), 3));
assignin('base','env_r',    fws(te, repmat(tile.r,   nrep,1), 3));
assignin('base','env_flag', fws(te, repmat(tile.flag,nrep,1), 1));
assignin('base','env_beta', fws(te, repmat(tile.beta,nrep,1), 1));
Sp = load(fullfile(root,'sim','model','out','adcs_profiles','adcs_profile_scan.mat'));
cp = double(Sp.cmd_speed_rpm(:));
tp = (0:1:2*P+600)';
assignin('base','prof_cmd_rpm', fws(tp, cp(mod(tp,86400)+1), 1));
try, set_param(mdl,'SimulationMode','accelerator');
catch, set_param(mdl,'SimulationMode','normal'); end
fprintf('[S4] 两轨 smoke（%s 模式，%.1e 步）…\n', ...
    get_param(mdl,'SimulationMode'), 2*P/sat.fixed_step_s);
tic; out = sim(mdl); tw = toc;
ck(true, 'S4', sprintf('sim 完成（墙钟 %.0f s）', tw));

% ---------- S5 通道齐全 + 栅格 ----------
[t01, tel] = flat(out.get('telemetry_01hz'));
[~,   tru] = flat(out.get('truth_01hz'));
[t1,  tl1] = flat(out.get('telemetry_1hz'));
[~,   lb1] = flat(out.get('labels_01hz'));                              %#ok<ASGLU>
wantT = {'eclipse_flag','beta_deg','rw_speed_rpm','rw_motor_current_a', ...
    'rw_cmd_torque_nm','rw_bearing_temp_c','bat_voltage_v','bat_current_a', ...
    'bat_temp_c','bat_soc'};
wantU = {'rw_friction_torque_nm','rw_wear_volume_mm3','rw_lube_level', ...
    'bat_soh','bat_lli','bat_lam'};
ck(isequal(sort(fieldnames(tel)), sort(wantT(:))) && ...
   isequal(sort(fieldnames(tru)), sort(wantU(:))), 'S5a', ...
   '双档通道名 = AE.1 冻结表');
ck(numel(t01) == 2*P/10 + 1 && max(abs(diff(t01)-10)) < 1e-6, 'S5b', ...
    sprintf('0.1 Hz 主档 N=%d（期望 %d）@10 s', numel(t01), 2*P/10+1));
ck(numel(t1) == 2*P + 1 && max(abs(diff(t1)-1)) < 1e-6, 'S5c', ...
    sprintf('1 Hz 精档 N=%d（期望 %d）@1 s', numel(t1), 2*P+1));

% ---------- S6 物理符号带 ----------
man = jsondecode(readu8(fullfile(here,'fixtures','sat_dev_expect.json')));
sid = 'RWA_dev_S001';
lman = select_manifest_line(man, sid, rw.friction_plan);
fl = round(tel.eclipse_flag);
ib = tel.bat_current_a;
ck(all(abs(ib(fl==2) - i_dis) < 1e-9) && all(abs(ib(fl==0) - i_chg) < 1e-9) ...
   && all(abs(ib(fl==1)) < 1e-9), 'S6a', '负载律 i(flag) 三段精确（AE.2）');
ck(min(tel.bat_voltage_v) > 3.3 && max(tel.bat_voltage_v) < 4.4, 'S6b', ...
    sprintf('v_bat∈(%.3f, %.3f) V', min(tel.bat_voltage_v), max(tel.bat_voltage_v)));
ck(min(tel.rw_bearing_temp_c) > 15 && max(tel.rw_bearing_temp_c) < 60, 'S6c', ...
    sprintf('T_brg∈(%.1f, %.1f) ℃', min(tel.rw_bearing_temp_c), ...
    max(tel.rw_bearing_temp_c)));
cmd1 = cp(mod(round(t1),86400)+1);
% [查8] I-P 双极点环对斜坡的真滞后 = (Kp+d)·R/Ki = 2R/p = 20.0 rpm
%（扫描斜坡 R=8 rpm/s, p=0.8；真机实测 20.06 = 20.0 + Ṁf/Ki 缓变项）。
% 带值唯一来源 = manifest checks.spd_track_max_err_rpm（oracle 推导+裕量）。
spd_band = lman.checks.spd_track_max_err_rpm;
ck(max(abs(cmd1 - tl1.rw_speed_rpm)) <= spd_band, 'S6d', ...
    sprintf('1 Hz 跟踪 max|cmd−ω|=%.2f rpm（≤%g，I-P 斜坡滞后 2R/p=20.0）', ...
    max(abs(cmd1 - tl1.rw_speed_rpm)), spd_band));
ck(all(diff(tru.rw_wear_volume_mm3) >= 0) && all(diff(tru.rw_lube_level) <= 0), ...
    'S6e', '磨损单调增 / 润滑单调减');
ck(min(tel.bat_soc) > 0.38 && max(tel.bat_soc) <= 1 + 1e-9, 'S6f', ...
    sprintf('SOC∈(%.3f, %.3f)', min(tel.bat_soc), max(tel.bat_soc)));

% ---------- S7 oracle 早期锚点（t≤2 轨子集；man 已于 S6 前装载） ----------
an = lman.anchors; if ~iscell(an), an = num2cell(an); end
for k = 1:numel(an)
    a = an{k};
    if a.t_s > 2*P || (~isfield(a,'rtol') && ~isfield(a,'atol')), continue; end
    j = round(a.t_s/10) + 1;
    switch a.ch
        case 'telemetry.bat.voltage_v',      got = tel.bat_voltage_v(j);
        case 'telemetry.rw.speed_rpm',       got = tel.rw_speed_rpm(j);
        case 'telemetry.rw.motor_current_a', got = tel.rw_motor_current_a(j);
        otherwise, continue
    end
    ok = (isfield(a,'rtol') && abs(got-a.value) <= a.rtol*abs(a.value)) || ...
         (isfield(a,'atol') && abs(got-a.value) <= a.atol);
    ck(ok, 'S7', sprintf('%s: %.6g（期望 %.6g）', a.name, got, a.value));
end

% ---------- S8 save_simout 结构冒烟（HDF5 面检） ----------
N = numel(t01);
tsm.t_days = t01/86400;
tsm.orbit = struct('eclipse_flag',tel.eclipse_flag,'beta_deg',tel.beta_deg);
tsm.rw = struct('speed_rpm',tel.rw_speed_rpm,'motor_current_a',tel.rw_motor_current_a, ...
    'cmd_torque_nm',tel.rw_cmd_torque_nm,'bearing_temp_c',tel.rw_bearing_temp_c);
in_off  = 10*(find(tile.flag ~= 0, 1) - 1);
seq = find(tile.flag ~= 0, 1); seq2 = seq + find(tile.flag(seq:end) == 0, 1) - 1;
out_off = 10*(seq2 - 1);
ev = sortrows([1 in_off; 2 out_off; 1 in_off+P; 2 out_off+P], 2);
K = size(ev,1); widx = zeros(K,4); ht = []; hid = []; hrow = [];
for w = 1:K
    a2 = max(0, ev(w,2)-sat.win_halfwidth_s); b2 = min(2*P, ev(w,2)+sat.win_halfwidth_s);
    widx(w,:) = [w ev(w,1) a2 b2];
    ss = (ceil(a2):floor(b2))'; ht = [ht; ss]; hid = [hid; repmat(w,numel(ss),1)]; %#ok<AGROW>
    hrow = [hrow; ss+1];                                                          %#ok<AGROW>
end
hsm.t_s = ht; hsm.window_id = hid; hsm.windows_index = widx;
hsm.orbit = struct('eclipse_flag',tl1.eclipse_flag(hrow),'beta_deg',tl1.beta_deg(hrow));
hsm.rw = struct('speed_rpm',tl1.rw_speed_rpm(hrow), ...
    'motor_current_a',tl1.rw_motor_current_a(hrow), ...
    'cmd_torque_nm',tl1.rw_cmd_torque_nm(hrow), ...
    'bearing_temp_c',tl1.rw_bearing_temp_c(hrow));
usm.cycle_index = floor(t01/P);
usm.rw = struct('friction_torque_nm',tru.rw_friction_torque_nm, ...
    'wear_volume_mm3',tru.rw_wear_volume_mm3,'lube_level',tru.rw_lube_level);
lsm = struct('rul_days', nan(N,1), 'hi', max(tru.rw_wear_volume_mm3/rw.v_th_mm3,0), ...
    'fail', zeros(N,1), 'attrs', struct('failure_time_days', NaN, ...
    'failure_mode_code', 0, 'criterion_text', 'selftest smoke (censored)'));
msm = struct('sample_id','RWA_dev_S001','config_yaml','# selftest smoke', ...
    'seed',int32(1001),'sim_model_version',sat.version, ...
    'lut_versions',readu8(fullfile(root,'sim','lut','lut_manifest.json')), ...
    'gmat_env_file','selftest','matlab_ver',version, ...
    'created_utc','1970-01-01T00:00:00Z','schema_version',sat.schema_version);
smk = fullfile(tempdir, 'sat_selftest_smoke.mat');
save_simout(smk, tsm, hsm, usm, lsm, msm);
gi = h5info(smk, '/');
gnames = arrayfun(@(g) g.Name, gi.Groups, 'UniformOutput', false);
ck(all(ismember({'/telemetry','/telemetry_hi','/truth','/labels','/meta'}, gnames)), ...
    'S8a', '五顶层组齐全');
li = h5info(smk, '/labels');
ck(numel(li.Attributes) >= 3 && ...
   all(ismember({'failure_time_days','failure_mode_code','criterion_text'}, ...
   {li.Attributes.Name})), 'S8b', '/labels 三属性齐全（§5.4）');
mi = h5info(smk, '/meta');
mgot = sort({mi.Datasets.Name});
mneed = sort({'sample_id','config_yaml','seed','sim_model_version', ...
    'lut_versions','gmat_env_file','matlab_ver','created_utc', ...
    'schema_version','meta_json'});
ck(isequal(mgot, mneed), 'S8c', '/meta 恰为九稳定字段 + meta_json（AF.1）');
mj = h5read(smk, '/meta/meta_json');
mjo = jsondecode(char(mj(:).'));
ck(numel(fieldnames(mjo)) == 9 && ~isfield(mjo, 'git_hash'), ...
    'S8d', 'meta_json 恰含九稳定字段且无旧 git_hash');
tdd = h5read(smk, '/telemetry/t_days');
ck(max(abs(double(tdd(:)) - t01/86400)) < 1e-12, 'S8e', 't_days 回读一致');
delete(smk);

% ---------- S9 ----------
if isempty(bad)
    fprintf('\n== sat_selftest: S0–S9 ALL PASS ==\n下一步：>> run_dev_s001 rwa（随后 bat）\n');
else
    error('sat_selftest:fail', '失败项: %s', strjoin(bad, ', '));
end

    function ck(ok, tag, msg)
        fprintf('  [%s] %s  %s\n', t3(ok), tag, msg);
        if ~ok, bad{end+1} = tag; end
    end
end

function s = t3(c)
if c, s = 'PASS'; else, s = 'FAIL'; end
end

function line = select_manifest_line(man, sid, friction_plan)
line = man.lines.(sid);
assert(isfield(line, 'by_friction_plan') && ...
    isfield(line.by_friction_plan, friction_plan), ...
    'sat_selftest:manifestPlan', ...
    'sat_dev_expect 缺少 friction plan %s 的 %s 锚', friction_plan, sid);
line = line.by_friction_plan.(friction_plan);
end

function s = fws(t, v, d)
s = struct('time',t,'signals',struct('values',v,'dimensions',d));
end
function [t, s] = flat(x)
% 与 run_dev_s001::flat_bus 同口径：时间轴取最长通道（Constant 占位如 src_lam
% 只记 1 点，不能用它定 t），标量常量通道广播到栅格（AE.2：lam≡0）。
fn = fieldnames(x); s = struct(); t = []; nmax = 0;
for k = 1:numel(fn)
    ts = x.(fn{k});
    if isa(ts,'timeseries') && numel(ts.Time) > nmax
        nmax = numel(ts.Time); t = ts.Time(:);
    end
end
for k = 1:numel(fn)
    ts = x.(fn{k});
    if ~isa(ts,'timeseries'), continue; end
    d = double(ts.Data); d = d(:);
    if numel(d) == numel(t), s.(fn{k}) = d;
    elseif numel(d) == 1,    s.(fn{k}) = repmat(d, numel(t), 1);
    else, error('flat:len', '通道 %s 长度 %d≠%d', fn{k}, numel(d), numel(t));
    end
end
end
