function summary = thermal_selftest()
% THERMAL_SELFTEST  任务 0709-01 验收标准的机器化（对应日程『验收标准（可检查）』列）
%
% 三个场景：A 常值桩（平衡不动点）、B = import_gmat('LEO550_B00', fixtures)
% （β≈0，3 轨、9 段地影 —— 验收主用例）、C = 'LEO550_B82'（零地影对照），
% 逐条断言：
%   T0 参数一致性：illum 查表形态 + 全部派生量 = 设计公式现算值（防手改失同步）
%   T1 数值健康：三场景全部记录信号有限（无 NaN/Inf，不发散）
%   T2 平衡不动点：常值桩下初值置于闭式平衡（辐射=全输入、节点差=q/G），
%      全程漂移 ≤ 1e-6 K —— 网络接线与 K→°C 换算链逐位锁定
%   T3 B00 地影响应：末轨 ΔT_brg ∈ [2,20] K（验收『数K~十几K』带）且温度谷
%      落在某本影段 [起, 止+1800 s] 滞后窗内（传导链滞后 ≈1.3×τ_whl）
%   T4 B82 无地影对照：末轨 ΔT_brg ≤ 2 K 且 ≤ 0.30×B00（初值取解析平衡，
%      量物理摆幅而非初值瞬态）
%   T5 准周期：B00 末两轨 ΔT 相对差 ≤ 15%、轨均漂移 ≤ 1 K（初值标定合格）
%   T6 均值梯度 = q/G：brg−whl / whl−str / bat−str 三对 ≤ 25%（周期稳态
%      逐节点能量平衡）
%   T7 热源链逐样本核对：模型 q_solar 输出与 env 数据现算公式逐样本相符
%      （本影恒 0、半影 ×0.5、余弦几何一次锁定）
%   T8 太阳矢量在岗：β≈0 时 max(ŝ·r̂)⁺≈1、β≈82° 时 ≈cos82°（env 几何自证）
%   T9 温度带：全节点 ∈ [-30,60] °C，电池 ∈ [0,40] °C（B00+B82 全程）
% 全过 → 出验收图 results/figures/thermal_net_accept.png 并打印 [OK]；
% 任一不过 → error 中止（当日修复，纪律同 rw_selftest / bat_selftest）。
%
% 用法（仓库根目录 rul-space/ 下，先跑过 build_thermal_net）：
%   >> addpath('sim/model'); thermal_selftest

here = fileparts(mfilename('fullpath'));          % sim/model
root = fileparts(fileparts(here));                % 仓库根（sim/model 上两级）
addpath(here);
addpath(fullfile(root,'sim','gmat'));             % import_gmat（I2 唯一生产者）
thermal_params();
thm = evalin('base','thm');

mdl = 'thermal_net_dev';
slx = fullfile(here,[mdl '.slx']);
assert(exist(slx,'file')==4 || exist(slx,'file')==2, 'thermal_selftest:noslx', ...
    '未找到 %s —— 请先运行 build_thermal_net', slx);
load_system(slx);                                 % PreLoadFcn 会重装 thm 与桩 env

% ---------- T0 参数一致性 ----------
ok0 = numel(thm.flag_bp)==numel(thm.illum) && all(diff(thm.flag_bp)>0) && ...
      all(thm.illum>=0 & thm.illum<=1) && all(diff(thm.illum)<=0) && ...
      abs(thm.q_track_w - thm.s0_w_m2*thm.alpha_eff*thm.a_track_m2) <= 1e-12 && ...
      abs(thm.q_zen_w   - thm.s0_w_m2*thm.alpha_eff*thm.a_zen_m2)   <= 1e-12 && ...
      abs(thm.q_int_w   - (thm.q_rw_motor_w+thm.q_rw_fric_w+thm.q_bat_w)) <= 1e-12 && ...
      abs(thm.gr_rad_w_k4 - thm.eps_rad*thm.sigma*thm.a_rad_m2) <= 1e-18 && ...
      abs(thm.tspace4_k4 - thm.t_space_k^4) <= 1e-9 && ...
      abs(thm.t0_brg_k - (thm.t0_brg_c+thm.c0_k)) <= 1e-12 && ...
      abs(thm.t0_bat_k - (thm.t0_bat_c+thm.c0_k)) <= 1e-12;
report(ok0,'T0 参数一致性', ...
    'illum 查表形态合规；q_track/q_zen/q_int/εσA/T_space⁴/t0_*_k 与设计公式逐项相符');

% ---------- 场景 A：常值桩平衡不动点（T2） ----------
q_c = thm.q_track_w + thm.q_zen_w*thm.stub_cos;
teq = equilibrium_k(q_c, thm);                    % [str whl brg bat] (K)
thm2 = thm;
thm2.t0_str_k = teq(1); thm2.t0_whl_k = teq(2);
thm2.t0_brg_k = teq(3); thm2.t0_bat_k = teq(4);
assignin('base','thm',thm2);
outA = sim(mdl,'StopTime',num2str(thm.stub_tend_s));
[~,a_str] = ts(outA.thm_str_c); [~,a_whl] = ts(outA.thm_whl_c);
[~,a_brg] = ts(outA.thm_brg_c); [~,a_bat] = ts(outA.thm_bat_c);
d2 = max([p2p(a_str) p2p(a_whl) p2p(a_brg) p2p(a_bat)]);
d2c = max(abs([a_str(1) a_whl(1) a_brg(1) a_bat(1)] - (teq' - thm.c0_k)));
ok2 = d2 <= 1e-6 && d2c <= 1e-6;
report(ok2,'T2 平衡不动点', ...
    sprintf(['常值桩 cos=%.2f：闭式平衡 T_str=%.2f °C 起步，%g s 内最大漂移 ' ...
    '%.2e K ≤ 1e-6；出口 °C 与 (T_eq−273.15) 偏差 %.2e ≤ 1e-6'], ...
    thm.stub_cos, teq(1)-thm.c0_k, thm.stub_tend_s, d2, d2c));
thermal_params();                                 % 还原 thm 与桩 env
thm = evalin('base','thm');

% ---------- 场景 B/C：import_gmat 夹具 env（I2 契约链实跑） ----------
fixdir = fullfile(root,'sim','gmat','fixtures');
[tB, qB, cB] = run_env_case(mdl, thm, fixdir, 'LEO550_B00', []);  % B00 用标定初值
eq82 = env_meanq(fixdir, 'LEO550_B82', thm);       % B82 初值 = 解析平衡（T4 注）
[tC, qC, cC] = run_env_case(mdl, thm, fixdir, 'LEO550_B82', eq82);

% ---------- T1 数值健康 ----------
ok1 = all(isfinite([cB.str; cB.whl; cB.brg; cB.bat; qB; ...
                    cC.str; cC.whl; cC.brg; cC.bat; qC; a_str]));
report(ok1,'T1 数值健康','A/B/C 三场景全部信号有限（无 NaN/Inf，不发散）');

% ---------- T3 B00 地影响应 ----------
t_orb = orbit_period(cB.r, tB);
mL = tB >= tB(end) - t_orb;
dt_brg00 = p2p(cB.brg(mL));
dt_bat00 = p2p(cB.bat(mL));
tL = tB(mL); [~,imin] = min(cB.brg(mL)); tmin = tL(imin);
spans = umbra_spans(tB, cB.flag);
lagwin = 1800;                                    % ≈2×τ_whl=C_whl/(G_ws+G_bw)
okp = any(tmin >= spans(:,1) & tmin <= spans(:,2) + lagwin);
[~,jn] = min(abs(tmin - spans(:,2)));
ok3 = dt_brg00 >= 2 && dt_brg00 <= 20 && okp;
report(ok3,'T3 B00 地影响应', ...
    sprintf(['末轨（T_orb=%.0f s）ΔT_brg=%.2f K ∈ [2,20]『数K~十几K』，' ...
    'ΔT_bat=%.2f K；温度谷 t=%.0f s 落在本影段[%.0f,%.0f]+%d s 滞后窗内' ...
    '（滞后 %+.0f s）'], t_orb, dt_brg00, dt_bat00, tmin, ...
    spans(jn,1), spans(jn,2), lagwin, tmin - spans(jn,2)));

% ---------- T4 B82 无地影对照 ----------
t_orb82 = orbit_period(cC.r, tC);
dt_brg82 = p2p(cC.brg(tC >= tC(end) - t_orb82));
ok4 = dt_brg82 <= 2 && dt_brg82 <= 0.30*dt_brg00;
report(ok4,'T4 B82 无地影对照', ...
    sprintf('末轨 ΔT_brg=%.3f K ≤ 2 K 且 ≤ 0.30×B00(%.2f K)（初值=解析平衡）', ...
    dt_brg82, dt_brg00));

% ---------- T5 准周期 ----------
mP = tB >= tB(end) - 2*t_orb & tB < tB(end) - t_orb;
dt_prev = p2p(cB.brg(mP));
r5 = abs(dt_brg00 - dt_prev)/max(dt_prev, 1e-9);
drift = abs(mean(cB.brg(mL)) - mean(cB.brg(mP)));
ok5 = r5 <= 0.15 && drift <= 1.0;
report(ok5,'T5 准周期', ...
    sprintf('末两轨 ΔT_brg %.2f→%.2f K（相对差 %.1f%% ≤ 15%%）；轨均漂移 %.3f K ≤ 1.0', ...
    dt_prev, dt_brg00, 100*r5, drift));

% ---------- T6 均值梯度 = q/G ----------
g1 = mean(cB.brg(mL) - cB.whl(mL)); w1 = thm.q_rw_fric_w/thm.g_bw_w_k;
g2 = mean(cB.whl(mL) - cB.str(mL)); w2 = (thm.q_rw_motor_w+thm.q_rw_fric_w)/thm.g_ws_w_k;
g3 = mean(cB.bat(mL) - cB.str(mL)); w3 = thm.q_bat_w/thm.g_bs_w_k;
rr = abs([g1 g2 g3] - [w1 w2 w3])./[w1 w2 w3];
ok6 = all(rr <= 0.25);
report(ok6,'T6 均值梯度=q/G', ...
    sprintf(['brg−whl=%.3fK(理论%.3f，差%.1f%%)；whl−str=%.3fK(理论%.3f，差%.1f%%)；' ...
    'bat−str=%.3fK(理论%.3f，差%.1f%%) ≤ 25%%'], ...
    g1, w1, 100*rr(1), g2, w2, 100*rr(2), g3, w3, 100*rr(3)));

% ---------- T7 热源链逐样本核对 ----------
qfB = q_formula(cB, thm); qfC = q_formula(cC, thm);
d7 = max([max(abs(qB - qfB)) max(abs(qC - qfC))]);
n_um = nnz(cB.flag == 2); n_pen = nnz(cB.flag == 1);
q_um = max(abs(qB(cB.flag == 2)));
ok7 = d7 <= 1e-6 && q_um <= 0;
report(ok7,'T7 热源链逐样本核对', ...
    sprintf(['模型 q_solar 与 env 现算公式逐样本 max|Δ|=%.2e W ≤ 1e-6' ...
    '（本影 %d 样本恒 0、半影 %d 样本 ×0.5、余弦几何一并锁定）'], d7, n_um, n_pen));

% ---------- T8 太阳矢量在岗 ----------
c00 = max(cB.cz); c82 = max(cC.cz);
ok8 = c00 >= 0.98 && c82 <= 0.16;
report(ok8,'T8 太阳矢量在岗', ...
    sprintf('max(ŝ·r̂)⁺ B00=%.3f ≥ 0.98，B82=%.3f ≤ 0.16（cos82°≈0.139）', c00, c82));

% ---------- T9 温度带 ----------
allc = [cB.str; cB.whl; cB.brg; cB.bat; cC.str; cC.whl; cC.brg; cC.bat];
batc = [cB.bat; cC.bat];
ok9 = all(allc >= -30 & allc <= 60) && all(batc >= 0 & batc <= 40);
report(ok9,'T9 温度带', ...
    sprintf('全节点 [%.1f,%.1f] °C ⊂ [-30,60]；电池 [%.1f,%.1f] °C ⊂ [0,40]', ...
    min(allc), max(allc), min(batc), max(batc)));

% ---------- 验收图（§9.4 图命名先例：仿真侧脚本写 results/figures/） ----------
figDir = fullfile(root,'results','figures');
if ~exist(figDir,'dir'), mkdir(figDir); end
fp = fullfile(figDir,'thermal_net_accept.png');
fig = figure('Visible','off','Position',[100 100 920 700]);
subplot(2,1,1); hold on;
ylo = min([cB.str; cB.bat]) - 2; yhi = max([cB.brg; cB.whl]) + 2;
hp = gobjects(size(spans,1),1);
for k = 1:size(spans,1)
    hp(k) = patch([spans(k,1) spans(k,2) spans(k,2) spans(k,1)]/60, ...
          [ylo ylo yhi yhi], [0 0 0], 'FaceAlpha',0.08, 'EdgeColor','none');
end
h1 = plot(tB/60, cB.str, 'LineWidth',1.0);
h2 = plot(tB/60, cB.whl, 'LineWidth',1.0);
h3 = plot(tB/60, cB.brg, 'LineWidth',1.4);
h4 = plot(tB/60, cB.bat, 'LineWidth',1.4);
grid on; ylim([ylo yhi]); ylabel('T [°C]');
title(sprintf(['thermal\\_net v1 验收：B00（β≈0°，3 轨，灰=本影）—— ' ...
    '末轨 ΔT\\_brg=%.1f K，ΔT\\_bat=%.1f K'], dt_brg00, dt_bat00));
legend([hp(1) h1 h2 h3 h4], {'umbra','structure','wheel body', ...
    'rw.bearing\_temp\_c','bat.temp\_c'}, 'Location','southwest');
subplot(2,1,2);
plot(tC/60, cC.brg, 'LineWidth',1.4); hold on;
plot(tC/60, cC.bat, 'LineWidth',1.4);
grid on; xlabel('t [min]'); ylabel('T [°C]');
legend('bearing (B82, no eclipse)','battery (B82)','Location','southeast');
exportgraphics(fig, fp, 'Resolution', 130);
close(fig);

summary = struct( ...
    'task_anchor', '0709-01', ...
    't0_pass', logical(ok0), ...
    't1_pass', logical(ok1), ...
    't2_pass', logical(ok2), ...
    't3_pass', logical(ok3), ...
    't4_pass', logical(ok4), ...
    't5_pass', logical(ok5), ...
    't6_pass', logical(ok6), ...
    't7_pass', logical(ok7), ...
    't8_pass', logical(ok8), ...
    't9_pass', logical(ok9), ...
    't0_t9_all_pass', logical(all([ok0 ok1 ok2 ok3 ok4 ok5 ok6 ok7 ok8 ok9])), ...
    'bearing_delta_t_b00_k', double(dt_brg00), ...
    'bearing_delta_t_b82_k', double(dt_brg82), ...
    'previous_orbit_bearing_delta_t_b00_k', double(dt_prev), ...
    'quasi_period_relative_difference', double(r5), ...
    'orbit_mean_drift_k', double(drift), ...
    'temperature_min_c', double(min(allc)), ...
    'temperature_max_c', double(max(allc)), ...
    'battery_temperature_min_c', double(min(batc)), ...
    'battery_temperature_max_c', double(max(batc)));

thermal_params();                                 % 收尾还原 base（thm + 桩 env）
fprintf('[OK] thermal_net v1 验收 T0–T9 全部通过；验收图已存 %s\n', fp);
fprintf('     截图入群口径：本命令行 [OK] 全绿 + 上述 PNG（进出地影温度按轨道周期波动）。\n');
end

% ======================================================================
function [t, q, c] = run_env_case(mdl, thm, fixdir, id, t0k_override)
% 用 import_gmat 产出的真实 env 覆写桩变量并仿真；返回记录栅格上的输出与
% env 派生量（结构体 c：str/whl/brg/bat[°C]、flag、r、sun、cz）
% 历元供给：B00 报表无 MJD 列（0707-02 显式历元测试样例），import_gmat 需经
% 'Epoch' 给历元；由 env_epoch_args 读 fixture_manifest.json 的 has_mjd 决定。
epArgs = env_epoch_args(fixdir, id);
env = import_gmat(id, 'InDir', fixdir, 'Save', false, 'Quiet', true, epArgs{:});
t    = env.t_s;
sun  = [env.sun_eci_x env.sun_eci_y env.sun_eci_z];
r    = [env.r_eci_x_km env.r_eci_y_km env.r_eci_z_km];
flag = double(env.eclipse_flag);
step = t(2) - t(1);
assert(abs(step - thm.test_dt_s) <= 1e-9, 'thermal_selftest:step', ...
    'env 步长 %g s ≠ thm.test_dt_s=%g s（附录 E.3 口径）', step, thm.test_dt_s);
assignin('base','env_sun', struct('time',t,'signals', ...
    struct('values',sun,'dimensions',3)));
assignin('base','env_r',   struct('time',t,'signals', ...
    struct('values',r,'dimensions',3)));
assignin('base','env_flag',struct('time',t,'signals', ...
    struct('values',flag,'dimensions',1)));
if ~isempty(t0k_override)                          % B82：初值=解析平衡（T4 注）
    thm.t0_str_k = t0k_override(1); thm.t0_whl_k = t0k_override(2);
    thm.t0_brg_k = t0k_override(3); thm.t0_bat_k = t0k_override(4);
    assignin('base','thm',thm);
end
out = sim(mdl,'StartTime',num2str(t(1)),'StopTime',num2str(t(end)));
[tt, brg] = ts(out.thm_brg_c);
[~ , bat] = ts(out.thm_bat_c);
[~ , whl] = ts(out.thm_whl_c);
[~ , str_] = ts(out.thm_str_c);
[~ , q  ] = ts(out.thm_qsolar_w);
assert(numel(tt)==numel(t) && max(abs(tt - t)) <= 1e-6, ...
    'thermal_selftest:grid', '记录栅格与 env 栅格未对齐');
rn = r ./ vecnorm(r, 2, 2);
c = struct('str',str_,'whl',whl,'brg',brg,'bat',bat, ...
    'flag',flag,'r',r,'sun',sun,'cz',max(0, sum(sun.*rn, 2)));
if ~isempty(t0k_override)                          % 还原参数（含桩 env）
    thermal_params();
end
end

function [teq, qm, czmax] = env_meanq(fixdir, id, thm)
% 无地影场景的解析平衡初值：轨道均值 q_solar 输入下的闭式平衡点
epArgs = env_epoch_args(fixdir, id);
env = import_gmat(id, 'InDir', fixdir, 'Save', false, 'Quiet', true, epArgs{:});
sun = [env.sun_eci_x env.sun_eci_y env.sun_eci_z];
r   = [env.r_eci_x_km env.r_eci_y_km env.r_eci_z_km];
rn  = r ./ vecnorm(r, 2, 2);
cz  = max(0, sum(sun.*rn, 2));
il  = interp1(thm.flag_bp, thm.illum, double(env.eclipse_flag), 'linear');
qm  = mean(il .* (thm.q_track_w + thm.q_zen_w .* cz));
czmax = max(cz);
teq = equilibrium_k(qm, thm);
end

function args = env_epoch_args(fixdir, id)
% 夹具历元供给（名值对元胞，供 import_gmat 展开）。GMAT 报表可缺 Sat.UTCModJulian
% 列（B00 即 0707-02 用于验证『显式历元』路径的样例），此时 import_gmat 需经
% 'Epoch' 参数给任务历元；有 MJD 列者（B82）自其反推、无需传。判据 has_mjd 与
% 历元串 epoch_gmat 均取自 fixture_manifest.json——与 import_gmat 自身 selftest
% E2 及其 Python 端口 run 分支同源同法，故 selftest env 与 oracle 消费的
% truth_env_*.csv 同历元、逐点一致。
man = jsondecode(fileread(fullfile(fixdir, 'fixture_manifest.json')));
c = man.cases.(id);
if isfield(c, 'has_mjd') && ~c.has_mjd
    args = {'Epoch', c.epoch_gmat};
else
    args = {};
end
end

function teq = equilibrium_k(q_solar_c, thm)
% 常值输入闭式平衡：结构板辐射 = 全部输入；节点差 = q/G（oracle 同式）
q_tot = q_solar_c + thm.q_earth_w + thm.q_int_w;
ts_ = (q_tot/thm.gr_rad_w_k4 + thm.tspace4_k4)^0.25;
tw_ = ts_ + (thm.q_rw_motor_w + thm.q_rw_fric_w)/thm.g_ws_w_k;
tb_ = tw_ + thm.q_rw_fric_w/thm.g_bw_w_k;
ta_ = ts_ + thm.q_bat_w/thm.g_bs_w_k;
teq = [ts_; tw_; tb_; ta_];
end

function qf = q_formula(c, thm)
% env 数据现算的热源公式（与子系统热源链逐块同式；T7 对表基准）
il = interp1(thm.flag_bp, thm.illum, c.flag, 'linear');
qf = il .* (thm.q_track_w + thm.q_zen_w .* c.cz);
end

function T = orbit_period(r, t)
% 由 r̂ 复现性求轨道周期（τ∈[3000,8000] s 内 dot 最大 + 抛物线细化；oracle 同式）
rn = r ./ vecnorm(r, 2, 2);
d = rn * rn(1,:)';
tau = t - t(1);
ii = find(tau >= 3000 & tau <= 8000);
[~, j] = max(d(ii)); k = ii(j);
T = tau(k);
if k > 1 && k < numel(t)
    y1 = d(k-1); y2 = d(k); y3 = d(k+1);
    den = y1 - 2*y2 + y3;
    if abs(den) > 1e-15
        T = tau(k) + 0.5*(y1 - y3)/den * (tau(k+1) - tau(k));
    end
end
assert(d(k) >= 0.999, 'thermal_selftest:orbit', ...
    'r̂ 复现性差（dot=%.4f），周期检测失效', d(k));
end

function spans = umbra_spans(t, flag)
% env 内全部本影段 [起 止]（按记录栅格；跨段判据 >1.1×步长）
tu = t(flag == 2);
assert(~isempty(tu), 'thermal_selftest:noumbra', 'B00 场景应含本影样本');
br = find(diff(tu) > 1.1*(t(2) - t(1)));
starts = [1; br + 1];
ends   = [br; numel(tu)];
spans = [tu(starts) tu(ends)];
end

function v = p2p(x)
v = max(x) - min(x);
end

function [t, x] = ts(v)
% To Workspace(Timeseries) → 列向量；顺带 squeeze 防 [N×1×1]
t = v.Time(:);
x = squeeze(v.Data); x = x(:);
end

function report(cond, label, detail)
if cond
    fprintf('[OK] %s: %s\n', label, detail);
else
    % 注意：detail 内可能含 '%'（如 T5/T6 的百分比），必须用 '%s' 字面透传，
    % 不能把拼好的消息再交给 error 的格式化器二次解析。
    error('thermal_selftest:fail', '[FAIL] %s: %s', label, detail);
end
end

