from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,re,shutil,subprocess
root=Path('/mnt/data/BRPHM/rul-space/work/f1_leo900_formal_20261017_r1');project=root/'project'
manifest_path=root/'evidence/base_source_tree_file_hashes.json'
raw=manifest_path.read_bytes();assert hashlib.sha256(raw).hexdigest()=='e8692f8e5dd0b02a47e8e2743781e098620617a8b1bfea95eb8414a5c75a46a4'
manifest=json.loads(raw);registered={row['path']:row for row in manifest['entries']}
pattern='env_r|env_sun|env_flag|env_beta|r_eci|sun_eci'
query=['rg','-n','--glob','*.m',pattern,str(project/'sim/model')]
files={};rg_available=shutil.which('rg') is not None
if rg_available:
 r=subprocess.run(query,capture_output=True,text=True,encoding='utf-8',timeout=20)
 if r.returncode not in (0,1):raise RuntimeError(r.stderr)
 hits=[line.split(':',2) for line in r.stdout.splitlines()]
else:
 hits=[];rx=re.compile(pattern)
 for p in sorted((project/'sim/model').rglob('*.m')):
  for i,line in enumerate(p.read_text(encoding='utf-8').splitlines(),1):
   if rx.search(line):hits.append((str(p),i,line))
for path_s,number,text in hits:
 p=Path(path_s)
 if p.is_symlink() or project not in p.resolve().parents:raise RuntimeError('unexpected source path')
 key=str(p.relative_to(project))
 if key not in files:
  content=p.read_bytes();entry=registered.get(key);sha=hashlib.sha256(content).hexdigest()
  files[key]={'path':str(p),'size':len(content),'sha256':sha,'registered_entry':entry,'matches_registry':entry is not None and entry.get('sha256')==sha,'text_utf8':content.decode('utf-8'),'matches':[]}
 files[key]['matches'].append({'line':int(number),'text':text})
print(json.dumps({'schema':'brphm-leo900-environment-consumer-static-capture-v1','observed_utc':datetime.now(timezone.utc).isoformat(),'manifest_sha256':hashlib.sha256(raw).hexdigest(),'query':query,'rg_available':rg_available,'search_method':'rg' if rg_available else 'python_pathlib_and_regex','files':files,'remote_writes':False,'raw_mat_or_tensor_decoded':False,'candidate_or_simulation_modified':False}))
